/** Hand-written theory for the eight catalogued studios. Each lab has its own
 * mechanism, boundary condition, and three worked examples. */
export type WorkedStudioExample = { title: string; setup: string; result: string };
export type StudioTheoryCopy = {
  principle: string;
  method: string;
  caution: string;
  examples: [WorkedStudioExample, WorkedStudioExample, WorkedStudioExample];
};

const topic = (principle: string, method: string, caution: string, first: string, second: string, third: string): StudioTheoryCopy => {
  const parse = (source: string): WorkedStudioExample => {
    const [title, setup, result] = source.split(" :: ");
    return { title, setup, result };
  };
  return { principle, method, caution, examples: [parse(first), parse(second), parse(third)] };
};

export const studioTheoryContent: Record<string, Record<string, StudioTheoryCopy>> = {
  "differential-equations": {
    home: topic("A differential equation relates an unknown function to its rates of change. Its order is the highest derivative; a family of solutions becomes one trajectory when enough initial conditions are supplied.", "Start by identifying order, linearity, and the source of each term. Use a slope field or phase portrait to check that the predicted behavior agrees with the equation.", "A numerical curve that looks plausible is not proof: substitute it into the equation and check initial data.", "Cooling tea :: T′=-0.2(T-22), T(0)=82 °C. :: T(t)=22+60e^(-0.2t); the temperature approaches 22 °C.", "Bank balance :: B′=0.05B with B(0)=1000. :: B(t)=1000e^(0.05t); growth is proportional to the balance.", "Spring :: x″+4x=0, x(0)=1, x′(0)=0. :: x(t)=cos(2t); the natural period is π."),
    explorer: topic("Order counts the highest derivative, while linearity asks whether y and its derivatives appear only to the first power with coefficients depending on the independent variable. A general solution carries arbitrary constants; an initial value fixes them.", "Rewrite the equation in standard form before classifying it. For a first-order equation, compare the right-hand side with f(x)g(y), P(x)y+Q(x), and Mdx+Ndy structures.", "A nonlinear forcing function of x alone does not make an equation nonlinear in y.", "Drug elimination :: C′=-0.3C is first-order linear and separable. :: C(t)=C₀e^(-0.3t); one initial concentration fixes C₀.", "Damped spring :: x″+2x′+5x=0 is second-order linear. :: Two independent initial values, position and velocity, select a motion.", "Crowded population :: P′=rP(1-P/K) is first-order nonlinear. :: The P² term breaks linearity and K is an equilibrium."),
    "slope-fields": topic("For y′=f(x,y), each point (x,y) gets a small line segment of slope f(x,y). A solution curve is tangent to every segment it passes through; equilibrium curves have zero slope.", "Evaluate f at a grid of points, draw short equal-length ticks, then trace curves following their direction. Compare several initial points to see the solution family.", "A direction field shows local slope, not the speed along a parametrized trajectory.", "Exponential growth :: y′=y has horizontal ticks at y=0. :: Curves above zero rise, and y=Ce^x stays tangent to the field.", "Cooling field :: T′=-0.2(T-20). :: T=20 is horizontal; trajectories above it slope down and below it slope up.", "Slope depends on x :: y′=x gives the same tick across each vertical line. :: Integrating yields y=x²/2+C, a family of parabolas."),
    "initial-value": topic("An initial value problem pairs an ODE with data such as y(x₀)=y₀. Under local continuity and a suitable Lipschitz condition in y, the initial point determines one nearby solution.", "Solve for the arbitrary constant after obtaining a general family, or start a numerical integrator exactly at (x₀,y₀). Verify both the equation and the initial condition.", "For a second-order equation one position alone is usually insufficient; velocity is also needed.", "Cooling :: T′=-0.1(T-20), T(0)=80. :: T(t)=20+60e^(-0.1t).", "Falling with drag :: v′=10-2v, v(0)=0. :: v(t)=5(1-e^(-2t)); terminal speed is 5.", "Second-order launch :: x″=-9.8, x(0)=0, x′(0)=20. :: x(t)=20t-4.9t²; both initial data are used."),
    separable: topic("An equation y′=f(x)g(y) is separable where g(y) is nonzero: dy/g(y)=f(x)dx. Integrating both sides produces an implicit or explicit solution family.", "Find equilibria from g(y)=0 before dividing, then separate and integrate. Apply an initial value only after retaining the possible constant solutions.", "Dividing by y can discard y=0, which may be a valid solution.", "Population :: P′=0.4P, P(0)=50. :: ln|P|=0.4t+C gives P=50e^(0.4t).", "Mixing :: y′=xy, y(0)=2. :: ln|y|=x²/2+C gives y=2e^(x²/2).", "Saturation :: y′=y(1-y), y(0)=1/2. :: Partial fractions give y=1/(1+e^(-t)); y=0 and y=1 are equilibria."),
    "homogeneous-first-order": topic("A first-order slope f(x,y) is homogeneous of degree zero when f(tx,ty)=f(x,y). Then it depends only on y/x, so y=vx reduces the equation to one in v and x.", "Set v=y/x and use y′=v+xv′. After substitution, separate the resulting equation, integrate, and replace v by y/x.", "This use of 'homogeneous' differs from the zero-forcing term in linear ODEs; the substitution also requires x≠0.", "Scale-invariant field :: y′=y/x, x>0. :: v+xv′=v, so v=C and y=Cx.", "Mixed ray slope :: y′=1+y/x. :: xv′=1; v=ln x+C, giving y=x(ln x+C).", "Quadratic ratio :: y′=(x²+y²)/(xy). :: With v=y/x, xv′=1/v; v²=2ln|x|+C."),
    exact: topic("M(x,y)dx+N(x,y)dy=0 is exact when it is dF=0 for a potential F. On a simply connected region with continuous partials, M_y=N_x is the local test.", "Integrate M in x to get F(x,y)=∫Mdx+g(y), differentiate in y, and choose g so F_y=N. The solution is F(x,y)=C.", "The matching-partials test can fail to guarantee one global potential if the domain has a hole.", "Circular levels :: 2x dx+2y dy=0. :: M_y=N_x=0; F=x²+y² and solutions are circles x²+y²=C.", "Product levels :: y dx+x dy=0. :: F=xy, so xy=C; the field follows hyperbolas.", "Missing y term :: (2xy+3)dx+(x²+4y)dy=0. :: Integrate M: F=x²y+3x+g(y); g′=4y, so F=x²y+3x+2y²=C."),
    "linear-first-order": topic("The standard linear equation y′+P(x)y=Q(x) has an integrating factor μ=e^(∫P dx). Multiplication makes the left side (μy)′.", "Identify P and Q, compute μ, integrate μQ, then divide by μ. Check the result by differentiation and apply initial data.", "Normalize the coefficient of y′ first; an equation can be linear even when P(x) is not constant.", "Charging circuit :: q′+2q=6, q(0)=0. :: μ=e^(2t); q=3(1-e^(-2t)).", "Variable coefficient :: y′+(1/x)y=x for x>0. :: μ=x; (xy)′=x², so y=x²/3+C/x.", "Decay with input :: y′+y=e^(-t), y(0)=0. :: (e^t y)′=1, hence y=te^(-t)."),
    bernoulli: topic("A Bernoulli equation y′+P(x)y=Q(x)yⁿ is nonlinear for n other than 0 or 1 but becomes linear under v=y^(1-n).", "Multiply by (1-n)y^(-n), use v′=(1-n)y^(-n)y′, solve the new first-order linear equation, then substitute back.", "The transformation may divide by y; check y=0 separately and restrict the domain when fractional powers occur.", "Quadratic response :: y′+y=y². :: Let v=1/y; v′-v=-1, so v=1+Ce^t and y=1/(1+Ce^t).", "Inverse decay :: y′-2y=3y³. :: v=y^(-2) gives v′+4v=-6, a linear equation.", "Degenerate case :: y′+2y=3y with n=1. :: This is already linear: y′=y, so y=Ce^t."),
    "method-selector": topic("A solving method follows the equation's structure. More than one label may apply; choose the method that produces the simplest valid transformation.", "Test separability, homogeneous ratio y/x, exactness, linear standard form, and Bernoulli power in that order. State the required domain and verify the result.", "Do not classify by appearance alone: multiplying an equation by a factor can reveal exactness or separability.", "Tank concentration :: C′=-kC. :: Separable and linear; separation immediately gives C=C₀e^(-kt).", "Implicit contour :: 2xy dx+x²dy=0. :: M_y=N_x=2x, so exactness gives x²y=C.", "Nonlinear power :: y′+y=xy². :: Bernoulli n=2; v=1/y converts it to a linear equation."),
    euler: topic("Euler's method advances y′=f(x,y) by y_(n+1)=y_n+h f(x_n,y_n). It follows the starting tangent for a whole step, so curvature creates truncation error.", "Evaluate the slope at the current point, multiply by step h, update x and y, and repeat. Halving h generally reduces first-order global error by about a factor of two.", "A small step does not guarantee stability for every equation; stiff decay can make explicit Euler oscillate or blow up.", "Growth :: y′=y, y(0)=1, h=0.1. :: First step y₁=1.1; exact e^0.1≈1.1052.", "Cooling :: T′=-0.2(T-20), T₀=80, h=1. :: Slope is -12 °C/min; Euler predicts T₁=68 °C.", "Stability :: y′=-10y, h=0.3. :: Update factor 1-10h=-2, so numerical values alternate and grow despite exact decay."),
    heun: topic("Heun's improved Euler method predicts an endpoint with Euler and averages the slopes at the start and predicted endpoint. It is an explicit second-order Runge–Kutta method.", "Compute k₁=f(x_n,y_n), y*=y_n+hk₁, k₂=f(x_n+h,y*), then y_(n+1)=y_n+h(k₁+k₂)/2.", "The second slope uses the predicted endpoint, not an exact future value.", "Growth :: y′=y, y₀=1, h=0.1. :: k₁=1, y*=1.1, k₂=1.1; y₁=1.105, close to e^0.1.", "Constant acceleration :: v′=2t, v(0)=0, h=1. :: Start/end slopes 0 and 2 average to 1; v₁=1, exact here.", "Cooling :: T′=-0.2(T-20), T₀=80, h=1. :: Predictor 68 gives end slope -9.6; corrected T₁=69.2."),
    rk4: topic("Classical RK4 samples four slopes: at the start, twice near the midpoint, and at the endpoint. Weighted average (k₁+2k₂+2k₃+k₄)/6 gives fourth-order global accuracy for smooth problems.", "Use k₁=f(x,y), k₂=f(x+h/2,y+hk₁/2), k₃=f(x+h/2,y+hk₂/2), k₄=f(x+h,y+hk₃), then advance by h times their weighted mean.", "Fourth-order accuracy does not remove stability restrictions or guarantee accuracy at discontinuities.", "Growth :: y′=y, y₀=1, h=0.1. :: RK4 gives 1.1051708, agreeing with e^0.1 to displayed precision.", "Cooling :: T′=-0.2(T-20), T₀=80, h=1. :: RK4 gives about 69.124 °C; exact value is 20+60e^(-0.2).", "Oscillation :: y″=-y becomes (y,v)′=(v,-y). :: RK4 follows the circular phase trajectory more closely than Euler at equal h."),
    "growth-models": topic("Exponential growth P′=rP assumes a constant per-capita rate. Logistic growth P′=rP(1-P/K) reduces that rate as population approaches carrying capacity K.", "Find equilibria first, separate variables or integrate numerically, then compare early-time growth with the limiting behavior.", "K is an environmental model parameter, not a fixed law; changing resources changes the forecast.", "Bacteria :: P′=0.4P, P(0)=100. :: After 5 hours P=100e²≈739 cells in the idealized model.", "Resource limit :: P′=0.4P(1-P/1000), P(0)=100. :: P(t)=1000/(1+9e^(-0.4t)); growth slows near 1000.", "Drug clearance :: C′=-0.3C, C(0)=20. :: The half-life is ln2/0.3≈2.31 time units."),
    "higher-order-linear": topic("A constant-coefficient equation ay″+by′+cy=0 has characteristic polynomial ar²+br+c. Distinct real roots give exponentials, a repeated root adds xe^(rx), and complex roots give damped sine and cosine.", "Find roots, choose the matching basis of independent solutions, then solve constants from position and derivative initial data.", "A repeated root does not give two copies of the same exponential; the second independent solution needs x.", "Two decay rates :: y″+3y′+2y=0. :: Roots -1,-2 yield y=C₁e^(-t)+C₂e^(-2t).", "Repeated root :: y″+2y′+y=0. :: (r+1)²=0 gives y=(C₁+C₂t)e^(-t).", "Oscillation :: y″+4y=0, y(0)=1, y′(0)=0. :: Roots ±2i give y=cos(2t)."),
    "undetermined-coefficients": topic("For constant-coefficient linear ODEs with polynomial, exponential, sine, or cosine forcing, a finite trial family is closed under differentiation. Substitute a matching trial for the particular solution.", "Find y_h, choose a trial matching the forcing, multiply by t enough times if it overlaps y_h, solve coefficients, and set y=y_h+y_p.", "This method does not generally handle arbitrary forcing such as ln t or tan t; use variation of parameters instead.", "Constant input :: y″+y=1. :: Trial y_p=A gives A=1, so y=C₁cos t+C₂sin t+1.", "Resonance :: y″+y=cos t. :: Cos t belongs to y_h; trial t(A sin t+B cos t) yields y_p=(t/2)sin t.", "Exponential forcing :: y′+2y=e^t. :: Trial Ae^t gives 3A=1, so y_p=e^t/3."),
    "variation-of-parameters": topic("Variation of parameters works for general forcing in a linear equation y″+p(x)y′+q(x)y=g(x). It lets the homogeneous coefficients vary with x.", "For independent y₁,y₂ and W=y₁y₂′-y₁′y₂, compute u₁′=-y₂g/W and u₂′=y₁g/W, then y_p=u₁y₁+u₂y₂.", "First divide by the coefficient of y″; the formulas assume the normalized forcing g and W≠0 on the interval.", "Non-polynomial input :: y″+y=sec t on |t|<π/2. :: With y₁=cos t, y₂=sin t, W=1; the method integrates -tan t and 1.", "Constant input :: y″+y=1. :: Integrals give a particular solution y_p=1, matching undetermined coefficients.", "Exponential input :: y″-y=e^(2t). :: y₁=e^t, y₂=e^(-t); a particular solution is e^(2t)/3."),
    "cauchy-euler": topic("In a Cauchy–Euler equation x²y″+axy′+by=0, powers y=x^m are eigenfunctions of the differential operator. Substitution gives m(m-1)+am+b=0.", "Solve the indicial quadratic. Distinct real roots give x^m; a repeated root adds x^m ln x; complex roots yield powers times sin and cos of ln x.", "Use an interval excluding x=0; ln x formulas conventionally work on x>0.", "Distinct powers :: x²y″-2xy′+2y=0. :: m²-3m+2=0, so y=C₁x+C₂x².", "Repeated power :: x²y″-xy′+y=0. :: (m-1)²=0, so y=x(C₁+C₂ln x).", "Log oscillation :: x²y″+xy′+y=0. :: m²+1=0, so y=C₁cos(ln x)+C₂sin(ln x)."),
    systems: topic("A linear system z′=Az is governed by the eigenvalues and eigenvectors of A. Real parts control growth or decay; imaginary parts create rotation in phase space.", "Compute trace, determinant, and eigenvalues, then sketch invariant directions and trajectories. Use z(0) to select a particular solution.", "A zero real part alone is inconclusive for nonlinear systems; linearization can require higher-order analysis.", "Saddle :: A=diag(1,-2). :: x=C₁e^t grows while y=C₂e^(-2t) decays; axes are invariant.", "Stable node :: A=diag(-1,-3). :: Both components decay toward the origin.", "Center :: A=[[0,-1],[1,0]]. :: Eigenvalues ±i yield circular trajectories with constant radius."),
    "phase-plane": topic("The phase plane places a system's state (x,y) at one point and draws vector arrows (x′,y′). A trajectory follows the arrows as time advances.", "Find equilibria by solving x′=y′=0, inspect the Jacobian near each, and trace several initial states to see basins and invariant curves.", "Trajectories of a well-posed autonomous system cannot cross at the same state and time direction.", "Predator–prey :: x′=x(1-y), y′=y(x-1). :: (1,1) is an equilibrium surrounded by cycles in this ideal model.", "Damped spring :: x′=v, v′=-x-0.2v. :: Trajectories spiral inward as energy dissipates.", "Saddle :: x′=x, y′=-y. :: Initial states move away along x and toward zero along y."),
    "mechanical-oscillations": topic("A mass–spring–damper obeys mx″+cx′+kx=F(t). The undamped natural frequency is √(k/m); ζ=c/(2√(mk)) separates underdamped, critical, and overdamped motion.", "Set m,k,c and initial displacement/velocity. Compare the roots of mr²+cr+k with the animation and the x(t) graph.", "Critical damping returns fastest without oscillation for this linear model; larger damping returns more slowly.", "Car suspension :: m=1,c=0.4,k=4. :: ζ=0.1; the motion oscillates while its envelope decays.", "Critical return :: m=1,k=4,c=4. :: ζ=1; the spring returns without overshoot.", "Undamped clock :: m=1,c=0,k=4. :: ω₀=2 rad/s and period π s."),
    "lcr-circuit": topic("A series LCR circuit follows Lq″+Rq′+q/C=E(t), where charge q is analogous to displacement, inductance L to mass, R to damping, and 1/C to stiffness.", "Compute natural angular frequency 1/√(LC) and damping ratio (R/2)√(C/L). Current is i=q′; inspect both charge and current when changing R.", "A charge peak is not a current peak: current is the time derivative of charge.", "Underdamped circuit :: L=1 H,C=0.25 F,R=1 Ω. :: ω₀=2 rad/s, ζ=0.25; charge rings down.", "Critical resistance :: L=1 H,C=0.25 F. :: R_crit=2√(L/C)=4 Ω.", "Initial capacitor :: q(0)=1 C,i(0)=0,E=0. :: Energy begins in the capacitor, then exchanges with the inductor."),
    "newton-cooling": topic("Newton's law models the rate of temperature change as T′=-k(T-T_a), where T_a is the ambient temperature and k>0 summarizes heat-transfer conditions.", "Separate or solve the linear equation: T(t)=T_a+(T₀-T_a)e^(-kt). The temperature gap halves after ln2/k.", "The model assumes a roughly constant ambient temperature and heat-transfer coefficient; a changing room needs a different forcing term.", "Hot coffee :: T₀=80 °C,T_a=20 °C,k=0.1/min. :: After 10 min, T≈42.1 °C.", "Warming bottle :: T₀=5 °C,T_a=25 °C,k=0.2/min. :: After 5 min, T≈17.6 °C, approaching from below.", "Half-gap time :: k=0.14/min. :: t_half=ln2/0.14≈4.95 min, independent of starting gap."),
  },
  geometry: {
    home: topic("Geometry studies properties that survive a construction or transformation. A useful investigation starts with a conjecture from measurement and ends with a reason it must hold.", "Drag dependent points, track invariant lengths and angles, then connect the picture to a congruence, similarity, or coordinate argument.", "A diagram can suggest a theorem but cannot prove it for every configuration.", "Bridge brace :: A triangular brace with sides 3,4,5 is rigid by SSS. :: Moving the frame without changing sides preserves its angles.", "Floor plan :: A 6 m by 4 m room has area 24 m². :: Doubling both dimensions quadruples area to 96 m².", "Wheel :: A wheel of radius 0.35 m travels 2πr≈2.20 m per revolution. :: Radius is a measurement, circumference is a derived distance."),
    construction: topic("A geometric construction records dependencies: a midpoint depends on endpoints, and a perpendicular bisector depends on a segment. Dragging a parent recomputes all children while preserving the defining constraints.", "Create free points first, attach lines or circles to them, then test each invariant by dragging the free points. Identify which object is constrained by which theorem.", "A point that merely looks centered is not a constructed midpoint unless its dependency enforces equal halves.", "Perpendicular bisector :: Segment AB runs from (0,0) to (4,0). :: Midpoint is (2,0); its perpendicular bisector is x=2.", "Circle through a point :: Center O=(1,1), A=(4,5). :: Radius OA=5; every point on the circle stays 5 units from O.", "Angle bisector :: A 60° angle is bisected by a ray. :: The dependent rays each form 30° with the original sides."),
    triangles: topic("Triangle rigidity follows from three non-collinear sides. Congruence preserves all lengths and angles; similarity preserves angles and scales every length by one factor.", "Use SSS, SAS, ASA, or AAS for congruence, and AA or proportional sides for similarity. Centers arise from intersecting special lines: medians, perpendicular bisectors, or altitudes.", "SSA does not always determine a unique triangle; it can produce two configurations.", "Roof truss :: Sides 3,4,5 make a right triangle because 3²+4²=5². :: Area is 3·4/2=6 square units.", "Scale model :: A 2-3-4 triangle enlarged by factor 3 becomes 6-9-12. :: Perimeter triples while area grows ninefold.", "Centroid :: Vertices (0,0),(6,0),(0,3). :: Median intersection is ((0+6+0)/3,(0+0+3)/3)=(2,1)."),
    circles: topic("A chord subtends a central angle twice the inscribed angle on the same arc. A tangent is perpendicular to the radius at contact, and secant products express power of a point.", "Identify the intercepted arc and whether the vertex lies at center, circle, or outside. Convert angle information to arcs before calculating lengths or areas.", "The inscribed-angle relation requires both angles to intercept the same arc.", "Clock face :: A 100° central arc gives a 50° inscribed angle. :: Moving the point around the opposite arc preserves 50°.", "Wheel sector :: r=6 cm and central angle 60°. :: Arc length is (60/360)·2π·6=2π cm; sector area is 6π cm².", "Tangent :: Circle center (0,0), contact (3,4). :: Radius vector (3,4); tangent direction can be (-4,3), whose dot product is zero."),
    polygons: topic("An n-gon can be triangulated into n−2 triangles, so its interior-angle sum is (n−2)180°. For a regular polygon each exterior turn is 360°/n.", "Count sides and diagonals, decompose area into triangles, and test whether a regular interior angle can fit an integer number around a point for tessellation.", "A regular pentagon does not tile the plane by copies meeting edge to edge because 108° does not divide 360°.", "Hexagonal tile :: n=6 gives interior angle 120°. :: Three tiles meet around a point because 3·120°=360°.", "Octagon :: n=8 has angle sum 1080°. :: Number of diagonals is n(n−3)/2=20.", "Regular square :: Side 5 cm. :: Area 25 cm²; perimeter 20 cm; apothem 2.5 cm."),
    transformations: topic("Translations, rotations, and reflections preserve distances and angles; they are isometries. A dilation of factor k preserves angles but multiplies lengths by |k| and areas by k².", "Represent a map by a rule or matrix, apply it to each vertex, then compare preimage and image. For compositions, respect order: applying A then B means B(A(P)).", "Reflection followed by rotation usually differs from rotation followed by reflection.", "Map pin :: Translate (2,3) by (-5,4). :: Image is (-3,7); segment lengths are unchanged.", "Quarter turn :: Rotate (3,1) 90° anticlockwise about origin. :: Image is (-1,3).", "Scale drawing :: Dilate a 3×4 rectangle by k=2. :: New dimensions 6×8; area rises from 12 to 48."),
    coordinate: topic("Coordinates turn geometric relationships into algebra. Distance comes from Pythagoras, midpoint averages endpoints, and slope measures rise per horizontal run.", "For A(x₁,y₁), B(x₂,y₂), compute Δx,Δy; then distance √(Δx²+Δy²), midpoint ((x₁+x₂)/2,(y₁+y₂)/2), and slope Δy/Δx when Δx≠0.", "Vertical lines have undefined slope, not slope zero.", "City blocks :: A=(1,2), B=(4,6). :: Straight-line distance √(3²+4²)=5; midpoint (2.5,4).", "Road grade :: Rise 3 m over run 60 m. :: Slope 3/60=0.05, or a 5% grade.", "Equal-distance locus :: Points equidistant from (0,0) and (4,0). :: Squaring distances yields x=2, the perpendicular bisector."),
    measurement: topic("Length is one-dimensional, area is two-dimensional, and volume is three-dimensional; scaling a figure by k changes these by k, k², and k³. Composite areas add, but internal edges do not add to outer perimeter.", "Choose units before calculating, decompose irregular figures into known shapes, and report uncertainty to match input precision.", "Adding the perimeters of pieces double-counts their shared boundary.", "L-shaped room :: A 6×4 rectangle loses a 2×1 corner. :: Area is 24−2=22 m².", "Scale map :: 1 cm represents 5 km; two towns are 3.2 cm apart. :: Actual distance is 16 km.", "Measurement uncertainty :: Length 10.0±0.1 cm and width 5.0±0.1 cm. :: Nominal area 50 cm²; uncertainty is approximately 1.5 cm² by first-order propagation."),
    proofs: topic("A visual proof isolates an invariant such as conserved area, equal angles, or a similarity ratio. The figure supports the argument; the written logic states why each step holds for all valid configurations.", "List givens, state the desired claim, and justify each transition with a definition or theorem. Use rearrangement only when pieces neither overlap nor leave gaps.", "Measuring one picture to many decimal places is still experimental evidence, not a proof.", "Pythagoras :: Four copies of a right triangle with legs a,b surround a center square. :: Comparing outer area gives a²+b²=c².", "Angle sum :: Draw a parallel through one triangle vertex. :: Alternate angles plus the vertex angle form a straight 180° line.", "Similarity :: Two triangles share angles 40° and 60°. :: Their third angles are 80° and AA establishes similarity; side ratios are equal."),
    solids: topic("A solid's net preserves the area of each face but changes their spatial arrangement. Surface area sums exposed faces; volume measures the space inside.", "Identify the base and height, choose a volume formula, then unfold the surface to count lateral and base areas separately.", "Slant height is needed for cone and pyramid surface area, while perpendicular height determines volume.", "Shipping cube :: Side 3 cm. :: Volume 27 cm³ and surface area 54 cm².", "Water tank :: Cylinder radius 2 m, height 5 m. :: Volume πr²h=20π m³; curved area 2πrh=20π m².", "Cone :: Radius 3, height 4. :: Slant height 5; total area πr(r+l)=24π, volume 12π."),
    ar: topic("AR geometry projects world points through a camera pose onto image pixels. To measure a physical length, the overlay needs a known scale or calibrated depth; apparent pixel length alone is insufficient.", "Anchor points to stable scene features, choose a reference measurement, and check camera movement before interpreting angles or lengths.", "Perspective makes parallel lines converge in the image, although they stay parallel in space.", "Room corner :: Calibrate a known 1 m floor edge spanning 200 px locally. :: A nearby 300 px edge is about 1.5 m at the same depth.", "Vertical wall :: A calibrated horizontal and vertical ray meet. :: Their world angle is 90° even if perspective distorts the image.", "Triangle overlay :: Measure sides 3,4,5 in one plane. :: The reconstructed angle opposite side 5 is 90°."),
  },
  trigonometry: {
    home: topic("Trigonometry connects an angle to a point on the unit circle. Cosine is horizontal projection, sine is vertical projection, and tangent is their ratio where cosine is nonzero.", "Use a reference triangle or unit circle to establish sign and magnitude, then carry the same ratios into waves, bearings, and measurements.", "Angles measured in degrees and radians are interchangeable only after conversion; derivative formulas normally assume radians.", "Ladder :: A 5 m ladder at 60° reaches 5sin60°≈4.33 m high. :: Projection converts length to height.", "Rotating wheel :: A point of radius 2 at 30° has coordinates (√3,1). :: x=2cos30°, y=2sin30°.", "Wave :: y=3sin(2πt) has amplitude 3 and period 1 s. :: One circle rotation corresponds to one cycle."),
    "unit-circle": topic("On the unit circle, the point at angle θ is (cosθ,sinθ). The signs come from the quadrant, and reference angles let one reuse first-quadrant exact values.", "Reduce an angle modulo 360° or 2π, find its reference angle, apply quadrant signs, and read coordinates. Use tanθ=sinθ/cosθ where defined.", "Tangent is undefined at 90° and 270° because cosθ=0.", "Reference angle :: θ=150° has reference angle 30°. :: (cosθ,sinθ)=(-√3/2,1/2).", "Full rotation :: 450° is coterminal with 90°. :: The terminal point is (0,1).", "Radians :: θ=5π/4. :: The point is (-√2/2,-√2/2), in quadrant III."),
    "right-triangle": topic("For an acute angle in a right triangle, sin=opposite/hypotenuse, cos=adjacent/hypotenuse, and tan=opposite/adjacent. Similar triangles show these ratios depend on angle, not size.", "Label the sides relative to the chosen angle before selecting a ratio; use a²+b²=c² to recover a missing side.", "The word 'opposite' changes when the reference angle changes.", "Surveying :: A 30° sightline over 20 m horizontal ground. :: Height difference is 20tan30°≈11.55 m.", "Ladder :: Hypotenuse 10 m and wall reach 8 m. :: Ground distance √(10²−8²)=6 m.", "Special triangle :: A 30-60-90 triangle has hypotenuse 12. :: Short leg 6 and long leg 6√3."),
    graphs: topic("For y=A sin(B(x−C))+D, |A| is amplitude, 2π/|B| is period, C is horizontal shift, and D is midline. Cosine starts at an extremum; tangent has period π and vertical asymptotes.", "Start from the parent function, scale vertically, adjust frequency, then shift. Mark midline, extrema, zeroes, and asymptotes before plotting.", "Tangent has no finite amplitude because it is unbounded.", "Daily temperature :: T(t)=20+5sin(2πt/24). :: Midline 20 °C, amplitude 5 °C, period 24 h.", "Compressed wave :: y=2cos(3x). :: Amplitude 2 and period 2π/3.", "Shifted wave :: y=sin(x−π/2). :: It equals −cos x and shifts π/2 to the right."),
    identities: topic("An identity is true on every point of its domain. The unit-circle equation x²+y²=1 becomes cos²θ+sin²θ=1; angle-sum rules follow from composing rotations.", "Transform one side of an identity at a time using known identities, keeping domain restrictions explicit before cancelling or dividing.", "Checking a few angles cannot prove an identity; dividing by sinθ can also discard cases where sinθ=0.", "Pythagorean :: θ=30°. :: sin²θ+cos²θ=1/4+3/4=1.", "Double angle :: θ=30°. :: sin(60°)=2sin30°cos30°=√3/2.", "Angle sum :: sin(45°+45°). :: sin45°cos45°+cos45°sin45°=1."),
    inverse: topic("Inverse trig functions return principal angles after restricting the original function to a one-to-one branch. Arcsin returns [-π/2,π/2], arccos [0,π], and arctan (-π/2,π/2).", "Check the input domain, find the reference angle, then select the principal value in the inverse function's range.", "arcsin(sinθ) need not equal θ outside the principal range.", "Slope angle :: Rise/run=1. :: arctan(1)=45°.", "Principal branch :: sin150°=1/2. :: arcsin(1/2)=30°, not 150°.", "Negative cosine :: arccos(-1/2). :: Principal value is 120°."),
    oblique: topic("The sine law relates sides to opposite-angle sines; the cosine law extends Pythagoras to a non-right included angle. An SSA specification can admit zero, one, or two triangles.", "Use cosine law for SAS/SSS, sine law for AAS/ASA, and check both possible angles in SSA. For two sides and included angle use area ab sinC/2.", "The arcsin key returns one principal angle; SSA may also permit its supplement.", "Survey triangle :: a=7,b=10,C=60°. :: c²=49+100−140cos60°=79, so c≈8.89.", "Land area :: Sides 20 m and 30 m include 45°. :: Area=20·30·sin45°/2≈212.1 m².", "Ambiguous case :: a=6,b=10,A=30°. :: sinB=10sin30°/6=5/6; both B≈56.4° and 123.6° fit."),
    waves: topic("A sinusoidal wave combines amplitude, frequency, and phase. Superposition adds displacements pointwise; nearby frequencies make beats with envelope frequency |f₁−f₂|.", "Write each signal as A sin(2πft+φ), add samples at the same time, and compare phase alignment, destructive interference, and Fourier harmonics.", "A beat frequency is the difference in frequencies, not their sum.", "Sound beat :: 440 Hz and 444 Hz tones. :: The loudness envelope pulses 4 times per second.", "Standing wave :: Two equal opposite-traveling waves. :: Their sum forms fixed nodes and oscillating antinodes.", "Second harmonic :: Fundamental 100 Hz. :: The second harmonic is 200 Hz and repeats twice per base cycle."),
    applications: topic("Trigonometric ratios turn measured angles and known baselines into inaccessible heights and distances. Bearings require a stated reference direction; periodic models require a period and phase origin.", "Draw the right triangle or coordinate axes, label known values and units, choose sine/cosine/tangent, then check that the answer is geometrically plausible.", "An angle of elevation is measured from horizontal, not from the vertical wall.", "Building height :: Stand 30 m away and measure elevation 40°. :: Height above eye level is 30tan40°≈25.2 m.", "Navigation :: Travel 10 km at bearing 060° from north. :: East component 10sin60°≈8.66 km; north component 5 km.", "Tide :: Water height 2+1.5cos(2πt/12). :: Range is 0.5–3.5 m and cycle is 12 h."),
    ar: topic("Camera-based trigonometry uses projected rays and a calibrated baseline to infer angles and lengths. The unit circle or triangle overlay visualizes ratios, but measurements depend on pose and scale.", "Calibrate horizontal distance, estimate an elevation angle from the camera, and apply h=d tanθ with an eye-height correction.", "A tilt or perspective error in the camera can dominate a small-angle height estimate.", "Tree :: Ground distance 12 m, elevation 35°, eye height 1.6 m. :: Tree height≈12tan35°+1.6≈10.0 m.", "Roof :: Ground distance 20 m, elevation 45°. :: Height above camera is 20 m.", "Wave projection :: Unit-circle marker rotates once in 2 s. :: The vertical screen trace is sinusoidal with frequency 0.5 Hz."),
  },
  "linear-algebra": {
    home: topic("Linear algebra studies vectors and maps that preserve addition and scalar multiplication. Matrix columns tell where basis vectors go; their combinations determine every transformed point.", "Begin with vectors, then compose matrices, solve linear systems, and inspect eigenvectors or factorizations to understand a map's structure.", "A matrix is a representation of a map relative to chosen bases; its entries alone are not the whole geometry.", "Image rotation :: R=[[0,-1],[1,0]]. :: R(1,0)=(0,1), a quarter turn.", "Mixture :: 2x+y=7 and x−y=2. :: Row reduction gives x=3,y=1.", "Area scale :: A=[[2,0],[0,3]]. :: det A=6, so a unit square maps to area 6."),
    vectors: topic("A vector encodes magnitude and direction. Dot product measures alignment and projection, while the 3D cross product gives a perpendicular direction whose length is parallelogram area.", "Add components coordinatewise; compute a·b=Σaᵢbᵢ, projection of a on b=(a·b/|b|²)b, and a×b by the determinant rule.", "A zero dot product means orthogonality only when the Euclidean inner product is being used.", "Wind and flight :: Airspeed (100,0) plus wind (0,20). :: Ground velocity (100,20), speed √10400≈102.", "Work :: Force (3,4) N moves an object (2,0) m. :: Work F·d=6 J; vertical force does no work here.", "Area :: a=(2,0,0), b=(0,3,0). :: |a×b|=6 square units."),
    matrices: topic("Matrix multiplication composes linear maps; entry (i,j) is row i of A dotted with column j of B. The inverse reverses a nonsingular map, while transpose swaps rows and columns.", "Check dimensions before multiplying, compute products in order, and verify A A⁻¹=I when an inverse exists.", "AB generally differs from BA; reversing order reverses the sequence of transformations.", "Rotate then stretch :: R=[[0,-1],[1,0]], S=diag(2,1). :: SR(1,0)=(0,1), while RS(1,0)=(0,2).", "Image pixels :: A 2×2 brightness mixing matrix acts on RGB-free two-channel data. :: Multiplying A by each pixel column applies the same linear rule.", "Inverse :: A=diag(2,4). :: A⁻¹=diag(1/2,1/4), restoring scaled coordinates."),
    "row-reduction": topic("Elementary row operations preserve a linear system's solution set. Pivots identify constrained variables; columns without pivots correspond to free parameters.", "Form [A|b], choose nonzero pivots, eliminate below and above, and inspect rows of zeros or contradictions before back-substitution.", "A row [0 0 | 1] means inconsistent, whereas [0 0 | 0] means an equation was redundant.", "Unique intersection :: x+y=5, x−y=1. :: Row reduction yields x=3,y=2.", "Parallel lines :: x+y=2, 2x+2y=5. :: Elimination produces 0=1; no solution.", "Infinite family :: x+y=2, 2x+2y=4. :: One pivot leaves y=2−x free."),
    "linear-transforms": topic("A linear map obeys T(u+v)=T(u)+T(v) and T(cu)=cT(u), so T(0)=0. Its matrix columns are the images of basis vectors.", "Move the basis vectors, assemble them as columns, then apply the matrix to a point or shape. Use determinant to track signed area change.", "A translation is affine rather than linear because it moves the origin.", "Shear :: A=[[1,2],[0,1]]. :: A(1,1)=(3,1); area scale det A=1.", "Reflection :: Swap-coordinate matrix [[0,1],[1,0]]. :: (2,5) maps to (5,2), reflection across y=x.", "Collapse :: A=[[1,0],[0,0]]. :: Every point maps onto the x-axis; determinant 0."),
    determinants: topic("The determinant is a signed area or volume scale. Its absolute value gives scale, sign gives orientation, and zero means the map collapses dimension.", "For 2×2, det[[a,b],[c,d]]=ad−bc. For higher dimensions, use elimination or cofactor expansion; det(AB)=det A det B.", "A negative determinant does not mean negative physical area; it records orientation reversal.", "Map scale :: A=diag(2,3). :: A unit square becomes area 6 because det A=6.", "Reflection :: A=diag(-1,1). :: det A=-1: area unchanged, orientation reversed.", "Dependent columns :: A=[[1,2],[2,4]]. :: det A=0, so the image of the unit square lies on a line."),
    "vector-spaces": topic("A span is the set of all linear combinations of given vectors. Independence means no nontrivial combination gives zero; a basis is independent and spans the space.", "Place vectors as columns, row-reduce, and count pivots for rank. Express a target vector in basis coordinates by solving Bc=v.", "More vectors than the ambient dimension are necessarily dependent, but fewer vectors need not be independent.", "Plane basis :: (1,0,0) and (0,1,0). :: Their span is the xy-plane and has dimension 2.", "Dependent set :: (1,2) and (2,4). :: The second is twice the first, so rank is 1.", "Coordinates :: Basis b₁=(1,1), b₂=(1,-1), target (4,2). :: Solve c₁=3,c₂=1."),
    eigenvectors: topic("An eigenvector v is a nonzero direction preserved by A: Av=λv. The eigenvalue λ tells the stretch or reversal along that direction.", "Solve det(A−λI)=0 for eigenvalues, then null(A−λI) for directions. Compare real and complex eigenvalues with the transformed grid and phase portrait.", "A rotation by 90° has no real eigenvector in the plane, though it has complex eigenvalues.", "Stretch :: A=diag(3,1/2). :: e₁ and e₂ are eigenvectors with λ=3 and 1/2.", "Reflection :: A=diag(1,-1). :: Along x the eigenvalue is 1; along y it is -1.", "Repeated eigenvalue :: A=[[2,1],[0,2]]. :: λ=2 twice but only one independent eigenvector."),
    orthogonality: topic("Orthogonal vectors have dot product zero. Projection decomposes a vector into a component along a subspace and an orthogonal residual; orthonormal bases make coordinates dot products.", "Normalize the target direction u, compute (v·u)u, subtract it from v, and check the residual dot u is zero.", "Projection onto the zero vector is undefined because its squared length is zero.", "Ramp force :: F=(3,4), horizontal direction (1,0). :: Horizontal projection is (3,0); residual (0,4).", "Diagonal direction :: v=(3,1), u=(1,1). :: Projection is (2,2) and residual (1,-1).", "Pythagoras :: v=(3,4), basis axes. :: Orthogonal components have squared lengths 9+16=25."),
    "least-squares": topic("When Ax=b has no exact solution, least squares minimizes ||Ax−b||². The fitted vector is the orthogonal projection of b onto the column space of A.", "Solve normal equations AᵀAx=Aᵀb when well-conditioned, or use QR/SVD for better numerical stability. Inspect residuals before trusting predictions.", "A low residual does not establish causation or justify extrapolation outside observed x-values.", "Line fit :: Points (0,1),(1,2),(2,2). :: Least-squares line is y≈1.167+0.5x.", "Overdetermined sensor :: Readings 4,5,6 for one constant value. :: Least-squares estimate is the mean 5.", "Projection :: A=(1,1)ᵀ, b=(2,0)ᵀ. :: Fitted vector is (1,1)ᵀ; residual (1,-1)ᵀ is orthogonal."),
    playground: topic("Composing transformations lets one study how a grid, unit square, or 3D object changes under successive linear maps. Order matters unless the matrices commute.", "Start with a simple basis, apply one map at a time, compare the product matrix, and track determinant and eigen-directions after composition.", "Visual similarity of two transformed shapes does not imply the matrices are equal on every vector.", "Rotate then scale :: R90 followed by S=diag(2,1). :: (1,0) maps to (0,1), while reversing order maps it to (0,2).", "3D mirror :: diag(-1,1,1) reflects across the yz-plane. :: Volume magnitude is preserved, orientation flips.", "Two shears :: [[1,1],[0,1]] squared. :: The product is [[1,2],[0,1]], doubling the shear amount."),
    "cayley-hamilton": topic("Every square matrix satisfies its own characteristic polynomial. For a 2×2 matrix, A²−tr(A)A+det(A)I=0, allowing high powers to reduce to I and A.", "Compute the characteristic polynomial, substitute A, verify the zero matrix, then rearrange to calculate powers or the inverse when det A≠0.", "The theorem applies to square matrices; it does not say each matrix entry individually satisfies the polynomial.", "Diagonal example :: A=diag(2,3), p(λ)=λ²−5λ+6. :: A²−5A+6I=0 entrywise.", "Inverse :: det A=6 and tr A=5 for diag(2,3). :: A⁻¹=(5I−A)/6=diag(1/2,1/3).", "High power :: A²=5A−6I. :: A³=5A²−6A=19A−30I."),
    diagonalization: topic("If A has a full basis of eigenvectors, A=PDP⁻¹ with D diagonal. Powers and exponentials become easy because D acts independently on each eigen-coordinate.", "Find eigenvalues, collect independent eigenvectors as P columns, verify AP=PD, and transform a vector into eigen-coordinates before applying D.", "A repeated eigenvalue does not guarantee enough eigenvectors for diagonalization.", "Two-axis stretch :: A=diag(2,3). :: Aⁿ=diag(2ⁿ,3ⁿ).", "Population steps :: A=P diag(1,0.8)P⁻¹. :: The 0.8 mode decays while the 1 mode persists.", "Defective case :: A=[[2,1],[0,2]]. :: One eigendirection prevents a 2×2 diagonalization."),
    "quadratic-forms": topic("A quadratic form xᵀAx describes conics or energy surfaces. For symmetric A, eigenvalue signs classify positive definite, negative definite, or indefinite behavior.", "Symmetrize coefficients, compute eigenvalues, rotate to eigenvector axes, and read the signs in the diagonal form.", "A zero determinant alone does not distinguish a flat valley from a saddle; inspect all eigenvalues.", "Bowl :: q=x²+2y². :: Both eigenvalues positive; level curves are ellipses and the origin is a minimum.", "Saddle :: q=x²−y². :: One positive and one negative eigenvalue; zero contours are y=±x.", "Rotated ellipse :: q=2x²+2xy+2y². :: Eigenvalues 3 and 1; principal axes lie along (1,1) and (1,-1)."),
    "principal-axes": topic("A symmetric matrix's orthogonal eigenvectors rotate a quadratic form into diagonal coordinates. The mixed xy term disappears on principal axes.", "Form the symmetric coefficient matrix, find its orthonormal eigenvectors Q, substitute x=Qu, and obtain uᵀ(QᵀAQ)u.", "The eigenvectors fix axis directions, but translation may also be needed when linear terms are present.", "Tilted ellipse :: x²+2xy+y²+2y²=1. :: Eigenvectors rotate axes; the cross term disappears in eigen-coordinates.", "Inertia :: Principal moments 2 and 5. :: Along eigen-axes, rotational energy has no mixed product term.", "Covariance :: Σ=[[2,1],[1,2]]. :: Eigenvalues 3 and 1; major data axis is (1,1)."),
    "matrix-factorizations": topic("Matrix factorizations expose different structure: LU organizes elimination, QR separates orthogonal directions from triangular weights, and SVD reveals input/output axes and singular scales.", "Choose LU for repeated square solves, pivoted LU for stability, QR for least squares, and SVD for rank or ill-conditioned problems.", "A small determinant does not by itself quantify numerical conditioning; singular values do.", "Repeated solves :: A=LU and many right-hand sides b. :: Solve Ly=b then Ux=y without refactoring A.", "Line fit :: Tall data matrix A=QR. :: Solve Rx=Qᵀb; QR avoids forming AᵀA.", "Image compression :: A≈U_kΣ_kV_kᵀ. :: Keeping the largest k singular values yields a rank-k approximation."),
    similarity: topic("Similar matrices B=P⁻¹AP represent the same linear map in different bases. They share characteristic polynomial, trace, determinant, and eigenvalues.", "Build P from new basis vectors, transform coordinates with P⁻¹, and verify B=P⁻¹AP. Compare invariant quantities before and after.", "Similar matrices need not have the same entries or eigenvectors expressed in the old coordinates.", "Axis swap :: A=diag(2,3), P swaps axes. :: B=diag(3,2), with the same eigenvalues.", "Trace :: A=[[1,2],[0,4]]. :: Every similar B has trace 5 and determinant 4.", "System state :: x′=Ax and x=Pz. :: New coordinates obey z′=(P⁻¹AP)z."),
    "jordan-form": topic("A defective matrix lacks a full eigenbasis. Jordan chains add generalized eigenvectors, producing blocks J=λI+N with nilpotent N.", "Solve (A−λI)v₁=0, then (A−λI)v₂=v₁. Use the chain as columns of P and verify P⁻¹AP has a Jordan block.", "Jordan form is mathematically revealing but numerically unstable near repeated eigenvalues.", "Two-state chain :: A=[[2,1],[0,2]]. :: v₁=(1,0), v₂=(0,1) form a length-two Jordan chain.", "Matrix powers :: J=2I+N with N²=0. :: Jⁿ=2ⁿI+n2^(n−1)N.", "ODE system :: x′=Jx. :: e^(Jt)=e^(2t)(I+tN), so one solution contains te^(2t)."),
  },
  "complex-numbers": {
    home: topic("A complex number z=a+bi is both an algebraic quantity and a point (a,b). Addition moves vectors, multiplication scales by moduli and adds arguments.", "Switch between rectangular a+bi and polar r(cosθ+i sinθ), choosing the form that simplifies the operation.", "Argument is multi-valued up to 2π; a principal argument chooses one branch.", "Navigation :: Move 3 east and 4 north. :: Displacement is 3+4i with modulus 5 and argument arctan(4/3).", "Rotation :: Multiply 2+i by i. :: i(2+i)=-1+2i, a 90° anticlockwise turn.", "Signal :: Phasor 5e^(iπ/3). :: Rectangular form is 2.5+(5√3/2)i."),
    "argand-plane": topic("The Argand plane places Re z on the horizontal axis and Im z vertically. Distance between z and w is |z−w|; conjugation reflects across the real axis.", "Plot coordinates, form a difference for distance, and use a modulus equation to identify circles or lines as loci.", "Argument depends on quadrant; plain arctan(b/a) can give the wrong quadrant.", "Distance :: z=3+4i and w=1−2i. :: |z−w|=|2+6i|=√40.", "Conjugate :: z=−2+5i. :: z̄=−2−5i and z z̄=29.", "Locus :: |z−(2+i)|=3. :: Points form a circle centered (2,1) with radius 3."),
    arithmetic: topic("Complex addition combines real and imaginary parts, while multiplication uses i²=−1. Division multiplies numerator and denominator by the denominator's conjugate.", "Carry out algebra in a+bi form; for multiplication or repeated powers, consider polar form because moduli multiply and arguments add.", "Never divide real and imaginary parts separately; (a+bi)/(c+di) is one quotient.", "AC phasors :: (2+3i)+(1−5i). :: Result is 3−2i.", "Rotation and scale :: (1+i)(2+i). :: Result 1+3i, since i²=−1.", "Impedance quotient :: (3+4i)/(1−i). :: Multiply by 1+i to get (-1+7i)/2."),
    "polar-forms": topic("Polar form z=r(cosθ+i sinθ)=re^(iθ) records magnitude r=|z| and direction θ=arg z. Multiplication multiplies radii and adds angles.", "Compute r=√(a²+b²), choose θ with the correct quadrant, then apply De Moivre's rule for powers or roots.", "At z=0 the argument is undefined; it is not zero degrees by convention.", "Convert :: z=−1+i. :: r=√2, θ=3π/4, so z=√2e^(3πi/4).", "Multiply :: 2e^(iπ/6)·3e^(iπ/3). :: Product 6e^(iπ/2)=6i.", "Power :: (cos30°+i sin30°)^3. :: Result cos90°+i sin90°=i."),
    rotation: topic("Multiplying by e^(iθ) rotates every complex point by θ about the origin without changing modulus; multiplying by re^(iθ) also scales by r.", "Represent each transform as a complex factor, multiply factors to compose transformations, then apply the product to z.", "Complex multiplication gives direct rotations about the origin; rotation about another center needs translation before and after.", "Quarter turn :: z=3+2i, multiply by i. :: Result -2+3i.", "Rotate about center :: Rotate z=2 around c=1 by 180°. :: c+(-1)(z-c)=0.", "Two turns :: Rotate 30° then 45°. :: Combined factor e^(i75°), so total turn is 75°."),
    roots: topic("The n roots of a nonzero complex number re^(iθ) have modulus r^(1/n) and arguments (θ+2πk)/n for k=0,…,n−1. They are evenly spaced on a circle.", "Convert to polar form, compute all k values, plot the roots, and verify by raising each to the nth power.", "Taking only the principal root misses n−1 other solutions.", "Square roots :: Solve z²=−1. :: Roots are i and −i.", "Cube roots of unity :: z³=1. :: Angles 0°,120°,240° give 1 and the two nonreal roots.", "Fourth roots :: z⁴=16. :: Modulus 2 and angles 0°,90°,180°,270° give ±2, ±2i."),
    euler: topic("Euler's formula e^(iθ)=cosθ+i sinθ connects exponential growth with circular rotation. The cosine and sine parts arise by grouping even and odd terms of the exponential Taylor series.", "Follow the unit-circle point while θ varies, then compare its real and imaginary projections or sum complex exponentials to recover trig identities.", "The exponent θ is in radians; replacing it with a degree number without conversion changes the value.", "Half turn :: e^(iπ)=−1. :: A π-radian rotation sends 1 to -1.", "Quarter turn :: e^(iπ/2)=i. :: The real projection is 0 and imaginary projection 1.", "Cosine from exponentials :: (e^(iθ)+e^(-iθ))/2. :: Imaginary parts cancel, leaving cosθ."),
    loci: topic("A complex locus is a set of points satisfying an equation such as |z-a|=r or |z-a|=|z-b|. Möbius maps (az+b)/(cz+d) send generalized circles to generalized circles where defined.", "Translate modulus or argument conditions into Cartesian geometry, mark excluded denominator zeros, and test representative points before drawing the entire set.", "An equation with a zero denominator excludes that point even if the rest of the curve looks continuous.", "Distance locus :: |z−(1+i)|=2. :: Circle center (1,1), radius 2.", "Bisector :: |z−1|=|z+1|. :: Squaring gives Re z=0, the imaginary axis.", "Inversion :: w=1/z maps |z|=2. :: Image circle has radius 1/2 around origin."),
    fractals: topic("Mandelbrot iteration uses z_(n+1)=z_n²+c starting at z₀=0; bounded orbits define the set. A Julia set fixes c and varies z₀ instead.", "Choose c, iterate, color by escape time when |z| exceeds 2, and zoom near the boundary to see new structure.", "Finite iteration cannot prove a point is in the set; it can only detect escape or give stronger evidence of boundedness.", "Outside point :: c=2. :: z₁=2,z₂=6; escape is immediate.", "Inside candidate :: c=0. :: Every iterate stays 0, so c is in the Mandelbrot set.", "Period-two orbit :: c=−1. :: Sequence 0,−1,0,−1,… remains bounded."),
    "waves-circuits": topic("A sinusoidal signal Re(Ae^(iωt)) is represented by phasor A. In AC analysis, impedance combines resistance and reactance: Z_R=R, Z_L=iωL, Z_C=1/(iωC).", "Add series impedances, divide voltage phasor by total impedance for current, and read magnitude and argument for amplitude and phase delay.", "Phasor analysis assumes a steady sinusoid at one frequency; transients require time-domain equations.", "Resistor :: V=10∠0° V, R=5 Ω. :: I=V/R=2∠0° A, in phase.", "Inductor :: ω=100 rad/s, L=0.1 H. :: Z_L=10i Ω; current lags voltage by 90°.", "Series RC :: R=3 Ω, capacitive reactance -4i Ω. :: |Z|=5 Ω; 10 V amplitude gives 2 A current amplitude."),
  },
  modelling: {
    home: topic("Mathematical modelling turns assumptions into equations, predictions, and tests against data. A model is useful when its variables, units, domain, and limitations are explicit.", "Define a measurable question, choose a mechanism, estimate parameters, compare predictions with observations, and revise when residual patterns reveal missing structure.", "A close fit to training data alone does not establish that a model predicts new conditions.", "Travel :: Constant speed 60 km/h for 2.5 h. :: Distance model d=vt predicts 150 km before stops or traffic.", "Population :: P′=0.1P, P₀=1000. :: Exponential model predicts P(10)≈2718, assuming constant per-capita growth.", "Forecast check :: Model predicts 20,22,24; observations are 19,22,26. :: Residuals -1,0,2 suggest a trend worth investigating."),
    motion: topic("Motion models connect position, velocity, and acceleration by x′=v and v′=a. Forces such as gravity and drag determine acceleration; numerical integration is needed when the forces depend on speed.", "Choose coordinates, state initial position and velocity, write force balance, solve or integrate, then compare the predicted path and energy changes.", "Ignoring air resistance can badly overpredict long-range projectile distance.", "Projectile :: Launch at 20 m/s and 30° with g=9.8 m/s². :: Ideal flight time 2v sin30°/g≈2.04 s.", "Braking :: Vehicle slows from 20 m/s at 5 m/s². :: Stop time 4 s and distance 40 m.", "Drag :: v′=10−2v from rest. :: Terminal speed is 5 m/s, not unbounded growth."),
    population: topic("Exponential growth assumes unlimited resources; logistic growth adds carrying capacity K. Harvesting subtracts a removal term, and age-structured models replace one count with linked cohorts.", "State births, deaths, resource limit, and intervention rates, then locate equilibria and test sensitivity to parameters.", "A carrying capacity estimated in one environment may change with climate or resource use.", "Exponential :: P₀=100,r=0.2/year. :: After 5 years P≈272 in the constant-rate model.", "Logistic :: K=1000,P₀=100,r=0.2/year. :: P(5)=1000/(1+9e^(-1))≈232.", "Harvest :: P′=0.2P(1-P/1000)−30. :: Equilibria solve 0.2P(1-P/1000)=30, and excessive harvest can remove positive equilibrium."),
    epidemics: topic("In SIR models S+I+R is conserved for a closed population. Infection transfers susceptible people to I at rate βSI/N, and recovery transfers I to R at rate γI.", "Estimate β and γ, calculate R₀≈β/γ near a fully susceptible start, and compare intervention scenarios by changing contact or removal rates.", "A lower peak does not necessarily mean fewer total infections without examining the entire trajectory and assumptions.", "Early spread :: β=0.3/day, γ=0.1/day. :: R₀≈3 when nearly everyone is susceptible.", "Vaccination :: If 70% are immune initially and R₀=3. :: Effective reproduction is about 0.9, below one.", "Recovery :: I=100, γ=0.1/day. :: About 10 people/day transfer from I to R at that instant."),
    finance: topic("Finance models track cash flows through time. Compounding grows balances, amortization splits each payment into interest and principal, and inflation changes purchasing power.", "Choose a period and effective rate, align payment timing with that period, and compute the balance after each contribution or repayment.", "A quoted annual rate is not the same as an effective annual rate when compounding occurs monthly.", "Savings :: ₹10,000 at 6% annual compounded yearly for 3 years. :: Future value 10000(1.06)³≈₹11,910.", "Loan :: ₹100,000 at 12% nominal annual with monthly rate 1%. :: First-month interest ₹1,000 before any principal repayment.", "Inflation :: A ₹100 basket rises 5% yearly for 2 years. :: Nominal cost ≈₹110.25; purchasing power falls."),
    optimization: topic("Optimization chooses decision variables to maximize or minimize an objective while satisfying constraints. Feasible solutions obey every resource, capacity, and timing bound.", "Write variables with units, objective and inequalities, inspect the feasible region, then test the optimum against active constraints and sensitivity.", "An unconstrained optimum can be physically impossible if it violates a resource limit.", "Production :: Profit 3x+2y with x+y≤10, x,y≥0. :: Producing 10 of x yields profit 30 if no other constraint binds.", "Transport :: Ship 5 units at ₹2 each and 3 units at ₹4 each. :: Route cost is ₹22; capacity constraints decide feasibility.", "Design :: Fence 40 m on all sides of a rectangle. :: Area x(20−x) peaks at x=10, a square of area 100 m²."),
    networks: topic("A weighted graph represents places or states as nodes and costs as edges. Dijkstra finds shortest paths with nonnegative weights; A* uses a heuristic lower bound to guide search.", "Define edge meanings and units, initialize distances, relax neighbors, and inspect the predecessor chain. For A*, use an admissible heuristic.", "Dijkstra is not valid with negative edge weights; an overestimating A* heuristic can lose optimality.", "Delivery :: A→B cost 2, B→C cost 3, A→C cost 8. :: Shortest A→C route is A→B→C with cost 5.", "Grid path :: Manhattan distance to goal is 6 steps. :: It is an admissible A* heuristic when each grid move costs at least 1.", "Road closure :: Edge B→C becomes cost 10. :: Direct A→C cost 8 becomes preferable."),
    regression: topic("Regression estimates how a response changes with predictors. In linear least squares, coefficients minimize squared residuals; residual plots reveal curvature, unequal variance, or outliers.", "Fit on observed data, inspect residuals, quantify prediction error, and validate on held-out or later observations.", "Correlation and a high R² do not prove a causal relationship.", "Sales :: Points (1,3),(2,5),(3,7). :: Fitted line y=2x+1 predicts 9 at x=4 if trend continues.", "Residual :: Model predicts 10 for observed 13. :: Residual observed−predicted is +3.", "Outlier :: Four points lie near y=x but one is (10,0). :: The influential point can strongly rotate the fitted line."),
    periodic: topic("Periodic models repeat after period T: f(t+T)=f(t). A harmonic model A sin(2πt/T+φ)+D captures a dominant cycle; multiple harmonics represent richer patterns.", "Estimate mean D, period T, amplitude A, and phase from landmarks; fit remaining error and test future cycles.", "A long-term upward trend cannot be represented by a pure sinusoid with fixed mean.", "Tide :: Mean 2 m, range 1–3 m, period 12 h. :: h(t)=2+cos(2πt/12) if high tide is t=0.", "Daylight :: Approximate annual mean 12 h and amplitude 3 h. :: A 365-day sinusoid spans roughly 9–15 h.", "Sound :: A 440 Hz tone. :: Period is 1/440≈2.27 ms."),
    numerical: topic("Numerical models approximate outcomes when exact formulas are impractical. Monte Carlo uses repeated random trials, iteration advances a recurrence, and sensitivity tests how input uncertainty affects predictions.", "Define the estimator or update rule, record seeds and step sizes, run repeated trials, then compare convergence and error.", "A larger number of simulations reduces random error slowly, typically in proportion to 1/√N.", "Monte Carlo π :: Sample points uniformly in a unit square. :: Four times the fraction inside the quarter circle estimates π.", "Euler cooling :: T′=-0.1(T-20), T₀=80, h=1. :: First numerical update is 74 °C.", "Sensitivity :: Travel d=vt at v=60±2 km/h over 2 h. :: Predicted distance is 120±4 km."),
    comparison: topic("Competing models should be judged on fit, complexity, plausibility, and predictions outside the fitting window. Residual patterns often reveal missing mechanisms.", "Fit candidates to the same training data, compare errors on held-out observations, then examine parameter meaning and sensitivity.", "The model with the smallest training error may overfit and perform worse on new data.", "Growth models :: Early population doubles rapidly, then flattens. :: Logistic fit captures a limit that exponential growth misses.", "Residual pattern :: Linear forecast errors are -3,-1,1,3 over time. :: Systematic trend suggests a missing curvature term.", "Model choice :: Two models have validation errors 4 and 5 but one uses ten extra parameters. :: Simpler model may be preferable if uncertainty overlaps."),
  },
  discrete: {
    home: topic("Discrete mathematics studies countable structures such as integers, sets, logical statements, and graphs. Proof often proceeds by cases, counting, induction, or invariants.", "Specify the objects and operations, test small cases, then justify a rule symbolically or with an algorithm and a correctness argument.", "A pattern seen in the first few integers is a conjecture, not a proof for all integers.", "Handshake network :: Four people each shake every other person's hand. :: Number of handshakes is C(4,2)=6.", "Clock :: 10 hours after 8 o'clock on a 12-hour clock. :: 8+10≡6 (mod 12).", "Route graph :: A tree with 7 vertices. :: It has exactly 6 edges if connected and acyclic."),
    "number-sense": topic("Integers, fractions, decimals, ratios, and powers represent quantities at different scales. Equivalent forms preserve value even when notation changes.", "Estimate order of magnitude first, convert to a common representation, then calculate and check units or sign.", "Adding fractions requires a common denominator; adding numerators and denominators directly is wrong.", "Recipe :: 3/4 cup plus 1/2 cup. :: Convert to quarters: 3/4+2/4=5/4 cups.", "Discount :: 20% of ₹750. :: 0.2·750=₹150; final price ₹600.", "Scientific scale :: 3×10⁵ divided by 6×10². :: Result 0.5×10³=500."),
    primes: topic("A prime has exactly two positive divisors, 1 and itself. Unique prime factorization underlies gcd, lcm, divisibility, and many cryptographic constructions.", "Sieve candidates up to √n for primality; factor composite numbers, then take minimum prime exponents for gcd and maximum exponents for lcm.", "The number 1 is neither prime nor composite.", "Sieve :: Test 97. :: No prime divisor ≤√97≈9.85 divides it; 97 is prime.", "Schedules :: 12=2²·3 and 18=2·3². :: gcd=6 and lcm=36, so cycles coincide every 36 units.", "Factor tree :: 84=2²·3·7. :: Its positive divisors count is (2+1)(1+1)(1+1)=12."),
    "modular-arithmetic": topic("Congruence a≡b (mod n) means n divides a−b. Residues wrap around a finite clock; a has an inverse mod n exactly when gcd(a,n)=1.", "Reduce residues, use the Euclidean algorithm for inverses, and solve linear congruences only after checking gcd(a,n) divides b.", "Division modulo n is not ordinary division; it requires a modular inverse.", "Clock :: 17 hours after 9 on a 12-hour clock. :: 9+17≡2 (mod 12).", "Inverse :: Solve 3x≡1 (mod 7). :: x≡5 because 3·5=15≡1.", "No solution :: Solve 4x≡3 (mod 6). :: gcd(4,6)=2 does not divide 3, so there is no residue solution."),
    "number-patterns": topic("Recursive sequences specify the next term from earlier terms; closed forms specify the nth term directly. Figurate numbers and Pascal's triangle have combinatorial interpretations.", "List initial terms, identify a recurrence, derive a formula when possible, and prove it by induction or counting.", "Matching the first few terms does not uniquely determine a sequence.", "Triangular dots :: 1+2+…+n. :: T_n=n(n+1)/2; T_5=15.", "Rabbit recurrence :: F₁=F₂=1, F_n=F_(n−1)+F_(n−2). :: The sixth term is 8.", "Pascal row :: Row 4 is 1,4,6,4,1. :: Entries count ways to choose k objects from 4."),
    combinatorics: topic("Counting depends on whether order matters, repetition is allowed, and choices are independent. Permutations arrange, combinations select, and inclusion–exclusion corrects overlap.", "Define the sample object precisely, apply product/sum rules, then divide by symmetry only when each object is counted the same number of times.", "Using n!/(n−r)! for an unordered committee overcounts by r!.", "Seats :: Assign 3 distinct roles from 5 students. :: 5·4·3=60 ordered outcomes.", "Committee :: Choose 3 from 5 without roles. :: C(5,3)=10.", "Overlap :: 20 study algebra, 15 study geometry, 8 study both. :: Number studying at least one is 20+15−8=27."),
    logic: topic("Propositional logic assigns truth values to statements. Equivalence means two expressions agree on every assignment; CNF is an AND of OR clauses, useful for SAT solving.", "Construct a truth table, compare columns, and use De Morgan's laws or distributivity to transform forms while preserving all truth assignments.", "A statement p→q is false only when p is true and q is false.", "Alarm :: p=door open, q=alarm sounds. :: p→q fails only if the door opens and alarm stays silent.", "De Morgan :: Not (rain AND cold). :: Equivalent to (not rain) OR (not cold).", "SAT :: (p∨q)∧(¬p∨q). :: q=true satisfies both clauses regardless of p."),
    sets: topic("Sets collect distinct elements. Union joins membership, intersection requires both memberships, Cartesian products form ordered pairs, and equivalence relations partition a set into classes.", "Write membership conditions, shade Venn regions or enumerate finite examples, and check reflexive, symmetric, and transitive properties for equivalence.", "An ordered pair (a,b) is generally different from (b,a); a set ignores order but a Cartesian product does not.", "Enrollment :: A={1,2,3}, B={3,4}. :: A∪B={1,2,3,4}, A∩B={3}.", "Product :: A={red,blue}, B={S,M}. :: A×B has four ordered size-color choices.", "Parity classes :: a~b when a−b is even. :: Integers split into even and odd equivalence classes."),
    graphs: topic("A graph contains vertices and edges. Connectivity, paths, trees, coloring, and flows answer different questions about the same network.", "Choose directed or undirected edges, label weights/capacities where needed, then use traversal, shortest-path, or flow algorithms that match those assumptions.", "A shortest path is not necessarily a minimum spanning tree; they optimize different objectives.", "Route :: A→B weight 2, B→C weight 3, A→C weight 9. :: Shortest A→C path costs 5 via B.", "Tree :: A connected acyclic graph on 8 vertices. :: It has 7 edges.", "Coloring :: A triangle graph. :: Three colors are required when adjacent vertices must differ."),
    algorithms: topic("An algorithm is a finite procedure with a correctness argument and cost model. Sorting, searching, Euclid's gcd, and graph traversal have different complexity bounds.", "State input assumptions, trace the steps on a small example, identify an invariant, and count operations as input size grows.", "A fast average case does not guarantee a fast worst case; complexity depends on the algorithm and input model.", "Binary search :: Sorted list of 1024 items. :: At most about 10 halvings locate an item.", "Euclid :: gcd(84,30). :: 84=2·30+24, 30=1·24+6, 24=4·6; gcd=6.", "Breadth-first search :: Unweighted route graph. :: The first visit to a node gives its shortest edge-count distance."),
    cryptography: topic("Classical ciphers transform symbols, while public-key systems use hard inverse problems. RSA relies on modular exponentiation and private exponent d satisfying ed≡1 mod φ(n).", "Work with small educational integers to see key generation, encryption, and decryption, then distinguish mathematical mechanism from real-world security practice.", "Tiny keys and textbook RSA are insecure; real systems require vetted padding and large keys.", "Caesar :: Shift A by 3 positions. :: A→D, Z→C after wrapping mod 26.", "RSA toy :: p=3,q=11,n=33,φ=20,e=3,d=7. :: Message 2 encrypts to 8; 8^7 mod 33 returns 2.", "Diffie–Hellman toy :: Modulus 23, generator 5, secrets 2 and 3. :: Public values 2 and 10 yield shared 8 mod 23."),
  },
  statistics: {
    home: topic("Statistics separates variation in a sample from uncertainty about a population. Descriptive summaries show observed data; inference uses a sampling model to estimate or test wider claims.", "Describe collection and units, visualize distribution and outliers, choose an estimator, then state its uncertainty and assumptions.", "A representative sample matters more than a large biased sample.", "Commute times :: 10,12,13,15,50 minutes. :: Median is 13; mean is 20, pulled upward by 50.", "Coin :: 52 heads in 100 flips. :: Sample proportion 0.52, not proof the coin's true probability is 0.52.", "Survey :: 60 of 100 support a policy. :: Estimate 0.60 with sampling uncertainty about √(0.6·0.4/100)≈0.049."),
    "data-explorer": topic("Exploratory data analysis inspects variable type, missingness, distribution, and relationships before fitting a model. Pairwise plots reveal association and outliers but not causality.", "Check units and missing values, plot marginal distributions, compare two-variable scatter or grouped views, and look for patterns that suggest a formal question.", "A striking scatter plot can be driven by one influential point or a hidden grouping variable.", "Shop data :: Prices 10,12,14 and units sold 9,7,5. :: A downward pairwise pattern suggests lower sales at higher price.", "Missing data :: 20 of 100 ages are blank. :: Report 20% missingness before calculating an age mean.", "Mixed groups :: Two classes each have positive study-score association but different baselines. :: Pooling may conceal the within-class pattern."),
    descriptive: topic("Center summarizes typical value, spread quantifies variation, and shape identifies skew or tails. Mean and standard deviation respond strongly to outliers; median and IQR are more resistant.", "Sort values for median and quartiles, compute mean and variance with the correct sample/population denominator, then compare multiple summaries.", "An outlier is not automatically an error; investigate its source before removal.", "Income :: 20,22,25,28,100 (thousands). :: Median 25 while mean 39, revealing right skew.", "Spread :: Data 2,4,6. :: Mean 4; sample variance [(−2)²+0²+2²]/2=4.", "IQR :: Q1=10,Q3=18. :: IQR=8; usual upper fence is 18+1.5·8=30."),
    "interactive-distributions": topic("A probability distribution assigns mass or density to possible outcomes. Discrete models sum point probabilities; continuous probabilities are areas under a density curve.", "Match mechanism to model: fixed trials for binomial, event counts for Poisson, waiting times for exponential, and bell-shaped measurements for normal.", "For a continuous distribution, probability at one exact point is zero even when density there is positive.", "Quality control :: X~Binomial(10,0.1). :: P(X=0)=0.9^10≈0.349.", "Calls :: X~Poisson(3) per hour. :: P(X=0)=e^(−3)≈0.050.", "Heights :: X~Normal(170,10²) cm. :: P(160<X<180)≈0.683 by the ±1σ rule."),
    experiments: topic("An experiment estimates probability by repeated outcomes. Relative frequency approaches theoretical probability under independent, identically distributed trials; conditional probability updates when information is known.", "Define the sample space, run trials, compare observed and theoretical frequencies, and use P(A|B)=P(A∩B)/P(B) for conditional events.", "A short run can deviate substantially from expected proportions without indicating a biased device.", "Coin :: 100 fair flips. :: Expected heads 50 but 46 or 54 are ordinary sample variation.", "Dice :: Sum 7 on two dice. :: Six of 36 equally likely pairs give probability 1/6.", "Medical test :: Prevalence 1%, sensitivity 90%, false-positive rate 5%. :: P(disease|positive)=0.009/(0.009+0.0495)≈15.4%."),
    counting: topic("Permutations count ordered selections; combinations count unordered selections. Factorials and Pascal's identity connect both, while tree diagrams expose staged choices.", "Ask whether order or repetition matters, multiply choices stage by stage, and divide by symmetry only when arrangements are equally represented.", "A probability numerator and denominator must count outcomes at the same granularity.", "Podium :: Top 3 from 5 runners. :: P(5,3)=5·4·3=60 ordered podiums.", "Team :: Choose 3 of 5 volunteers. :: C(5,3)=10 teams.", "Binomial coefficient :: Coefficient of x² in (1+x)^4. :: C(4,2)=6."),
    clt: topic("The sample mean has expected value μ and standard error σ/√n for independent draws. Under broad conditions, its distribution approaches normal as n grows even when the population is skewed.", "Draw many samples of the same size, compute each mean, plot their distribution, and compare its center and width with μ and σ/√n.", "The central limit theorem does not say the raw observations become normally distributed.", "Wait times :: Population σ=12 min, sample size n=36. :: Standard error of mean is 12/6=2 min.", "Sample size :: Increase n from 25 to 100. :: Standard error halves because √n doubles.", "Skewed population :: Individual service times are right-skewed. :: Means of large independent samples become more bell-shaped."),
    "confidence-intervals": topic("A confidence interval is a data-dependent procedure with a stated long-run capture rate. For a mean with known σ, estimate x̄±z*σ/√n; wider confidence or higher noise makes wider intervals.", "Choose the estimand and sampling model, compute a standard error, choose a critical value, and interpret the interval as a plausible parameter range.", "A fixed 95% interval does not assign 95% probability to the fixed population parameter in the usual frequentist interpretation.", "Mean :: x̄=50,σ=10,n=100. :: Approximate 95% interval 50±1.96=48.04 to 51.96.", "Proportion :: 60 successes in 100 trials. :: p̂=0.60, SE≈0.049, approximate 95% margin ≈0.096.", "Coverage simulation :: Build 100 independent 95% intervals. :: About 95 should contain μ on average, but any run may differ."),
    hypothesis: topic("A hypothesis test compares data with a null model. The p-value is the probability, under that null, of a result at least as extreme as the observed one.", "State H₀ and H₁, choose a statistic and null distribution, compute p, compare with α, then discuss effect size and study design.", "A p-value is not the probability that H₀ is true, and statistical significance is not practical importance.", "Mean test :: H₀:μ=10, sample estimate 12, SE=1. :: z=2 and two-sided p≈0.0455.", "Decision :: p=0.02 with α=0.05. :: Reject H₀ at 5%; this does not prove H₁ exactly.", "Power :: True effect grows while noise stays fixed. :: Rejection becomes more likely under the alternative."),
    correlation: topic("Correlation r summarizes linear association between two numeric variables; least-squares regression fits a prediction line by minimizing squared vertical residuals.", "Plot the scatter first, fit the line, inspect residuals and influential points, and limit predictions to a defensible x-range.", "A strong r may hide nonlinear structure, confounding, or an influential outlier.", "Perfect line :: (1,2),(2,4),(3,6). :: r=1 and fitted y=2x.", "Prediction :: Fit y=3+2x. :: At x=4 the predicted response is 11, provided x=4 is in scope.", "Residual :: Observed 14, predicted 11. :: Residual is +3; positive means the point lies above the line."),
    anova: topic("ANOVA compares between-group variation with within-group variation. Under equal means, the F ratio MS_between/MS_within is typically near one; large values challenge the null.", "Define groups and randomization, calculate sums of squares and degrees of freedom, form F, then inspect residuals and follow-up comparisons.", "A significant F says at least one mean differs, not which specific pair differs.", "Three treatments :: Group means 10,10,10 with similar spread. :: Between-group sum of squares is near zero, so F is small.", "Changed treatment :: Means 10,10,20 with low within-group noise. :: Between-group variation rises and F becomes large.", "Design :: Randomly assign 30 plots equally to 3 fertilizers. :: Each treatment gets 10 plots, reducing selection bias."),
  },
  algebra: {
    home: topic("Algebra represents unknown quantities and relationships with symbols. An identity is true for every allowed value; an equation asks which values make a statement true.", "Keep the domain visible, transform expressions with reversible rules, and check candidate solutions in the original problem.", "Squaring or multiplying by an expression that can be zero can add or lose solutions.", "Budget :: Three tickets cost ₹450. :: 3x=450 gives x=₹150 per ticket.", "Rectangle :: Length x+2, width x. :: Area x(x+2)=x²+2x.", "Growth :: Deposit ₹1000 at 5% yearly. :: Balance after n years is 1000(1.05)^n."),
    expressions: topic("Like terms have the same variable powers, so their coefficients combine. Expansion uses distributivity; factorization reverses it.", "Identify terms and domain restrictions, combine coefficients, distribute products, then verify an equivalent form by expansion.", "2x and 2x² are unlike terms; their exponents cannot be merged.", "Shop bill :: 3 notebooks at x each plus 2 more. :: 3x+2x=5x.", "Area :: Rectangle sides x+3 and x+2. :: Area (x+3)(x+2)=x²+5x+6.", "Factor :: x²+7x+12. :: (x+3)(x+4) because 3+4=7 and 3·4=12."),
    equations: topic("An equation stays equivalent when the same reversible operation is applied to both sides. Linear equations isolate x; quadratics may need factoring or the quadratic formula; inequalities reverse direction after multiplying by a negative.", "Simplify both sides, preserve balance, solve, and substitute each candidate into the original equation.", "Squaring √x=-2 would produce x=4, but the original equation has no real solution.", "Taxi fare :: 50+12d=170. :: Subtract 50 and divide by 12: d=10 km.", "Quadratic :: x²−5x+6=0. :: Factor (x−2)(x−3)=0; roots 2 and 3.", "Inequality :: −2x<6. :: Divide by −2 and reverse sign: x>−3."),
    functions: topic("A function assigns one output to each allowed input. Transformations change a graph predictably; composition applies one function after another, while an inverse reverses a one-to-one function.", "State domain, evaluate and graph parent behavior, then apply shifts/scales in the correct order. For an inverse, swap x and y and solve.", "A relation can fail to be a function if one input has two outputs; an inverse may require a restricted domain.", "Pricing :: f(n)=20n+50. :: Five items cost f(5)=₹150.", "Shift :: g(x)=(x−2)²+3. :: The parabola x² moves right 2 and up 3.", "Composition :: f(x)=2x, g(x)=x+1. :: f(g(3))=8, while g(f(3))=7."),
    polynomials: topic("The factor theorem links roots and factors: f(r)=0 iff (x−r) divides f(x). Degree and leading coefficient determine end behavior; multiplicity determines whether a graph crosses or touches an axis.", "Factor or divide, count roots with multiplicity, and check signs around each root before sketching.", "A repeated even-multiplicity root touches the axis without changing sign.", "Roots :: x²−9=(x−3)(x+3). :: Zeroes are ±3.", "Multiplicity :: f(x)=(x−2)²(x+1). :: At x=2 the graph touches; at x=-1 it crosses.", "End behavior :: f(x)=−2x³+x. :: As x→∞, f(x)→−∞ because the leading term dominates."),
    systems: topic("A solution of a system satisfies every equation simultaneously. Graph intersections, substitution, elimination, and row reduction are equivalent ways to find the same feasible set.", "Choose an efficient method based on coefficients, inspect whether equations are dependent or inconsistent, and check the solution in all originals.", "Parallel lines have no solution; identical lines have infinitely many.", "Tickets :: Adult x plus child y: x+y=10, 5x+3y=42. :: Eliminate y to get x=6,y=4.", "Intersection :: y=2x+1 and y=−x+7. :: 2x+1=−x+7 gives (2,5).", "Dependent :: 2x+2y=8 and x+y=4. :: Same line, so infinitely many solutions."),
    exponents: topic("Exponent laws follow from repeated multiplication, while logarithms invert exponentials. For a>0,a≠1, log_a(a^x)=x on the relevant domain.", "Use common bases to solve exponential equations or take logarithms; enforce positive log arguments and check transformed equations.", "log(x+y) is not log x+log y; logarithm addition corresponds to multiplication.", "Doubling :: 2^x=32. :: x=5.", "Compound interest :: 1000(1.1)^t=2000. :: t=ln2/ln1.1≈7.27 years.", "Log domain :: log₁₀(x−3)=2. :: x−3=100, so x=103>3."),
    sequences: topic("An arithmetic sequence changes by constant difference d; a geometric sequence changes by constant ratio r. A recurrence gives the next term, while a closed form gives term n directly.", "Inspect consecutive differences and ratios, write the nth term, and use a sum formula when accumulating values.", "A sequence with ratio zero or changing signs needs careful indexing before applying a geometric sum formula.", "Savings :: Add ₹100 each month starting at ₹500. :: Month n amount a_n=500+100(n−1).", "Doubling :: Start 3, multiply by 2. :: Fifth term 3·2⁴=48.", "Arithmetic sum :: 1+2+…+20. :: Sum=20·21/2=210."),
    proof: topic("Algebraic proof establishes a claim for every allowed value using definitions and valid transformations. A counterexample disproves a universal claim with one valid case.", "State assumptions, justify each equality or implication, and separate one-way implications from equivalences.", "Testing many values can support a conjecture but cannot prove a universal identity.", "Odd square :: n=2k+1. :: n²=4k(k+1)+1, so every odd square is odd.", "Identity :: (a+b)². :: Distributivity gives a²+2ab+b² for all real a,b.", "Counterexample :: Claim: all primes are odd. :: The prime 2 disproves the claim."),
    cas: topic("A computer algebra system manipulates symbolic expressions under stated assumptions. Exact simplification, factorization, solving, and differentiation are different operations with different domains.", "Enter an expression with variables and assumptions, choose the operation, then verify the result by substitution or differentiation.", "A symbolic answer can omit branch or domain restrictions unless those assumptions are supplied.", "Factor :: Input x²−5x+6. :: CAS returns (x−2)(x−3); expanding verifies it.", "Differentiate :: Input x³−2x. :: Output 3x²−2, checked by power rule.", "Solve :: Input x²=4 over reals. :: Solutions are x=−2 and x=2, not only the principal square root."),
    advanced: topic("Advanced algebra connects systems, functions, polynomial structure, and symbolic proof. A useful workflow alternates between exact manipulation, visualization, and numeric checking.", "Identify the algebraic structure first, choose a symbolic method, and verify special cases or boundary values.", "A numerical match at sampled points is evidence, not an identity proof.", "Parametric root :: x²−(a+1)x+a=0. :: Factor (x−1)(x−a); roots 1,a, coincident when a=1.", "Matrix system :: [[2,1],[1,2]](x,y)=(3,3). :: Solution x=y=1.", "Inverse composition :: f(x)=3x−2. :: f⁻¹(x)=(x+2)/3 and f⁻¹(f(t))=t."),
    classic: topic("Classic algebra uses balance, substitution, and equivalent expressions to solve unknowns. The central rule is to preserve equality while simplifying both sides.", "Collect like terms, isolate the variable, and check the result in the original equation or expression.", "A transformation that divides by a variable needs a separate check when that variable is zero.", "Balance :: 3x+4=19. :: Subtract 4 and divide by 3 to get x=5.", "Factor :: x²−16. :: Difference of squares gives (x−4)(x+4).", "Substitute :: y=2x+1 and x=3. :: y=7, the coordinate is (3,7)."),
  },
  "algebraic-structures": {
    home: topic("An algebraic structure is a set together with operations satisfying axioms. Closure, associativity, identity, inverses, and order laws distinguish semigroups, monoids, groups, rings, and lattices.", "State the carrier set and operation, test each axiom with symbols or a complete finite table, then look for counterexamples.", "An identity element depends on the operation: 0 for addition, 1 for multiplication.", "Integers :: (ℤ,+) has identity 0 and inverse −a for each a. :: It forms a group under addition.", "Natural numbers :: (ℕ,+) has 0 if included but lacks additive inverses. :: It is a monoid, not a group.", "Subsets :: Power set under union. :: Identity is empty set and union is associative and idempotent."),
    "structure-test": topic("A structure test checks axioms in the right order: closure, associativity, identity, and inverses. A single counterexample is enough to reject an axiom.", "Choose a set and operation, evaluate all pairs for closure and all triples for associativity when finite, then locate an identity and each inverse.", "Commutativity is not required for a group; it is an extra property of abelian groups.", "Even integers :: Even+even is even. :: Closure holds; 0 and negatives also remain even, giving an additive group.", "Subtraction :: On integers, (5−3)−1=1 but 5−(3−1)=3. :: Associativity fails.", "Nonzero rationals :: Under multiplication, identity 1 and inverse 1/a exist. :: This is an abelian group."),
    "cayley-tables": topic("A Cayley table lists every output of a finite binary operation. Rows and columns reveal closure, identity, inverses, and commutativity; associativity requires checking triples.", "Label elements consistently, fill each cell a*b, locate an identity row and column, then search each row for the identity to find inverses.", "A symmetric table proves commutativity, not associativity.", "Mod 3 addition :: Elements 0,1,2. :: Row for 2 is 2,0,1; identity is 0 and inverse of 2 is 1.", "XOR :: Elements 0,1 with bitwise XOR. :: Table has 0 as identity and each element self-inverse.", "Left projection :: Define a*b=a on {0,1}. :: Table rows are constant; no two-sided identity exists."),
    "semigroups-monoids": topic("A semigroup has an associative operation. A monoid is a semigroup with an identity; inverses are not required.", "Check closure and associativity, then test a candidate identity on both sides of every element.", "A left identity need not be a right identity, so test both directions.", "Strings :: Concatenation is associative. :: Empty string is identity, so strings form a monoid.", "Positive integers :: Multiplication is associative with identity 1. :: It is a monoid; most elements lack inverses within positive integers.", "Max operation :: max(a,b) on nonnegative integers. :: Identity is 0 because max(0,a)=a."),
    "posets-lattices": topic("A partial order is reflexive, antisymmetric, and transitive. A lattice additionally has a meet (greatest lower bound) and join (least upper bound) for each pair.", "Draw a Hasse diagram without reflexive and transitive edges, then find meet and join from the order.", "Incomparable elements are allowed in a poset; a total order requires every pair to be comparable.", "Divisibility :: On {1,2,3,6}, a≤b when a divides b. :: Meet of 2 and 3 is gcd=1; join is lcm=6.", "Subsets :: Under inclusion, meet is intersection and join is union. :: {1,2}∧{2,3}={2}.", "Schedule priority :: Tasks A and B can be incomparable. :: A partial order can still place both before task C."),
    "boolean-algebra": topic("Boolean algebra combines AND, OR, and NOT with identities such as distributivity and De Morgan's laws. Sets and digital circuits provide concrete models.", "Build a truth table for the expression, simplify with identities, then check the resulting circuit or set operation.", "The distributive laws work in both directions; a visual circuit simplification must preserve every input row.", "Access rule :: A AND (B OR C). :: Equivalent to (A AND B) OR (A AND C).", "De Morgan :: NOT(A AND B). :: Equivalent to (NOT A) OR (NOT B).", "Absorption :: A OR (A AND B). :: Always equals A, so one gate branch can be removed."),
  },
  "number-systems": {
    home: topic("Number systems expand to support new operations: natural numbers count, integers include negatives, rationals express ratios, and reals include limits such as √2.", "Place each number in the smallest familiar set that contains it, convert representations, and compare locations on the real line.", "A finite decimal is rational; an infinite nonrepeating decimal can be irrational.", "Temperature :: −5 °C requires an integer below zero. :: Natural counting numbers cannot represent it.", "Recipe :: 3/4 cup is rational. :: Its decimal 0.75 terminates.", "Diagonal :: A unit square diagonal is √2. :: It is real and irrational, not expressible as a fraction of integers."),
    rational: topic("A rational number has form p/q with integers p,q and q≠0. Its decimal expansion terminates or repeats; arithmetic is closed under addition, subtraction, multiplication, and division by nonzero rationals.", "Use a common denominator for addition, reduce by gcd, and connect fraction, decimal, and point on the number line.", "The denominator cannot be zero; 0/0 is not a rational number.", "Shared pizza :: 2/3+1/4. :: Common denominator 12 gives 8/12+3/12=11/12.", "Repeating decimal :: 0.333… . :: Let x=0.333…; 10x−x=3, so x=1/3.", "Scale :: 3/5 of 20 km. :: Distance is 12 km."),
    irrational: topic("An irrational real cannot equal p/q for integers p,q≠0. Its decimal expansion neither terminates nor repeats; common examples include √2, π, and e.", "Use geometric constructions or bounds to locate irrationals, and distinguish exact symbols from rounded measurements.", "A decimal approximation such as 1.414 is rational even though it approximates irrational √2.", "Square diagonal :: Side 1 gives diagonal √2 by Pythagoras. :: √2≈1.4142 but has no exact fraction form.", "Circle :: Circumference divided by diameter is π. :: A radius-1 circle has exact circumference 2π.", "Sum :: √2+(2−√2). :: Result 2 is rational; sums involving irrationals need not be irrational."),
    "real-line": topic("Every real number has a position on the number line. Order compares positions, absolute value measures distance from zero, and intervals encode sets of positions.", "Place reference integers, estimate irrational positions, then use inequalities and interval notation to show ranges.", "A strict inequality excludes endpoints; a closed interval includes them.", "Distance :: |-3−2|. :: Points -3 and 2 are 5 units apart.", "Bound :: -2≤x<4. :: Interval is [-2,4), including -2 but excluding 4.", "Root :: √5≈2.236. :: It lies between 2 and 3 because 4<5<9."),
    hierarchy: topic("The standard containment chain is ℕ⊂ℤ⊂ℚ⊂ℝ, with irrationals in ℝ outside ℚ. Complex numbers extend ℝ by adding i with i²=−1.", "Classify a number by exact definition rather than its appearance, and distinguish a number's value from one representation of it.", "Depending on convention, 0 may or may not be included in ℕ; state the chosen convention.", "Negative count :: −7 is integer, rational (-7/1), and real. :: It is not natural.", "Fraction :: 0.125=1/8. :: It is rational despite decimal notation.", "Complex root :: Solve x²+1=0. :: Solutions ±i are complex but not real."),
    concepts: topic("Number concepts include closure, order, density, completeness, and representation. Between two distinct rationals lies another rational; real completeness also fills limits missing from ℚ.", "Test an operation on a chosen set, compare neighboring values with averages, and use sequences to understand limiting behavior.", "A dense subset can still omit points: rationals are dense in reals but do not contain √2.", "Between fractions :: Between 1/3 and 1/2. :: Their average 5/12 lies strictly between them.", "Closure :: Integers under subtraction. :: 3−5=−2 remains an integer.", "Limit :: Decimal approximations 1.4,1.41,1.414,… . :: They approach √2, which is not rational."),
    practice: topic("Reliable number-system practice combines exact calculation with estimation. Fractions and roots should be simplified before rounding; reported precision should match the task.", "Classify values, perform operations in exact form, estimate magnitude, then convert to decimals only when needed.", "Premature rounding can accumulate error across repeated operations.", "Fraction sum :: 5/6−1/4. :: 10/12−3/12=7/12≈0.5833.", "Radical :: √50. :: Factor 25·2 to obtain exact 5√2≈7.071.", "Percent error :: Approximate π as 3.14. :: Absolute error ≈0.00159 and relative error ≈0.051%."),
  },
  calculus: {
    home: topic("Calculus studies limits, instantaneous change, accumulation, and multivariable variation. Derivatives describe local rates; integrals aggregate continuously varying quantities.", "Read the units and geometry first, form a limit or sum, apply the relevant theorem, and check the result against a graph or physical interpretation.", "A memorized derivative or integral without its domain and initial conditions may answer the wrong question.", "Velocity :: s(t)=t² metres. :: Instantaneous velocity s′(3)=6 m/s.", "Distance :: v(t)=2t m/s for 0≤t≤3. :: ∫₀³2t dt=9 m traveled.", "Optimization :: A(x)=x(10−x). :: A′=10−2x=0 at x=5, the maximum area 25."),
    limits: topic("A limit describes the value approached near a point, regardless of the function's value exactly there. Continuity requires the two-sided limit to equal that value.", "Test from left and right, simplify removable factors only for x near the point, and use a graph or table to check the algebra.", "Substituting x=a into a 0/0 form gives indeterminacy, not a numeric limit.", "Removable hole :: f(x)=(x²−4)/(x−2). :: For x≠2, f=x+2, so lim(x→2)f=4.", "One-sided jump :: f(x)=|x|/x near 0. :: Left limit -1 and right limit 1; two-sided limit does not exist.", "Infinite limit :: f(x)=1/x² near 0. :: Values grow without bound on both sides; no finite limit."),
    derivatives: topic("The derivative f′(x) is the limit of average slopes [f(x+h)−f(x)]/h as h→0. It gives tangent slope and instantaneous rate.", "Differentiate with product, chain, and quotient rules as needed, then interpret sign and units at a point.", "The derivative of a product is not the product of derivatives; use (fg)′=f′g+fg′.", "Motion :: s=t³ metres. :: v=s′=3t² and v(2)=12 m/s.", "Tangent :: f=x² at x=3. :: Slope f′(3)=6, so tangent y−9=6(x−3).", "Chain rule :: f(x)=sin(x²). :: f′(x)=2x cos(x²)."),
    "derivative-applications": topic("Derivative signs identify increasing/decreasing intervals, while critical points and endpoint checks locate extrema. Second derivatives describe curvature and acceleration.", "Form an objective with a domain, differentiate, solve f′=0, test critical points and endpoints, then interpret units.", "A critical point can be a minimum, maximum, or neither; f′=0 alone is not enough.", "Fencing :: Fixed perimeter 40 m gives A=x(20−x). :: Maximum at x=10 m with area 100 m².", "Acceleration :: s=t³−3t². :: v=3t²−6t and a=6t−6; acceleration vanishes at t=1.", "Related rates :: A=πr² and dr/dt=2 cm/s at r=3 cm. :: dA/dt=2πr·dr/dt=12π cm²/s."),
    integration: topic("An integral accumulates infinitesimal contributions. The Fundamental Theorem of Calculus links accumulation to antiderivatives: ∫_a^b f(x)dx=F(b)−F(a) when F′=f.", "Choose signed area or physical accumulation, find an antiderivative or numerical approximation, and include bounds and units.", "A definite integral may be negative; physical area uses absolute values where the graph crosses the axis.", "Velocity :: v=2t on 0≤t≤3. :: Displacement ∫₀³2t dt=9 m.", "Area :: f=x² on [0,2]. :: ∫₀²x²dx=8/3 square units.", "Net change :: Flow rate 5−t L/min from 0 to 4. :: Accumulated volume ∫₀⁴(5−t)dt=12 L."),
    "integration-techniques": topic("Integration techniques reverse differentiation patterns. Substitution handles composition, integration by parts reverses a product rule, and partial fractions split rational functions.", "Inspect the integrand's structure, choose a substitution or decomposition, integrate, and differentiate the answer to verify.", "A substitution in a definite integral must also transform the limits or return to the original variable.", "Substitution :: ∫2x cos(x²)dx. :: Let u=x²; result sin(x²)+C.", "By parts :: ∫x e^x dx. :: x e^x−∫e^x dx=(x−1)e^x+C.", "Partial fractions :: ∫1/(x²−1)dx. :: Split into 1/2[1/(x−1)−1/(x+1)] and integrate logs."),
    "integral-applications": topic("Integrals compute volume, work, mass, and average value by summing thin pieces. The integrand must include the correct cross-sectional geometry and units.", "Draw a representative slice, write its differential contribution, choose limits, then integrate.", "Using radius where the formula needs radius squared can produce a dimensional error in volume.", "Disk solid :: Rotate y=x on [0,2] about x-axis. :: V=π∫₀²x²dx=8π/3.", "Work :: Force F(x)=3x N moves from x=0 to 2 m. :: Work ∫₀²3x dx=6 J.", "Average :: Temperature T(t)=20+2t over 0–4 h. :: Average (1/4)∫₀⁴Tdt=24 °C."),
    "differential-equations": topic("A differential equation in calculus connects an unknown function with its derivative. Slope fields visualize first-order solutions; initial data select a trajectory.", "Classify separable or linear structure, solve symbolically when possible, then compare with Euler or RK4 approximations.", "A slope field is local; a curve must be tangent to its arrows at every point.", "Growth :: y′=0.2y, y(0)=5. :: y=5e^(0.2t).", "Cooling :: T′=-0.1(T−20), T₀=80. :: T(t)=20+60e^(-0.1t).", "Euler :: y′=y, y₀=1, h=0.1. :: First approximation 1.1 versus exact e^0.1≈1.1052."),
    "series-parametric-polar": topic("A series approximates a function by sums; parametric curves specify x(t),y(t), and polar curves specify radius r(θ). Convergence and coordinate choice determine what conclusions are valid.", "For a series, identify a convergence test and its hypotheses. For curves, compute derivatives from the chosen parameter and check where denominators vanish.", "An alternating series may converge conditionally even when its absolute-value series diverges.", "Geometric series :: Σ_(n=0)^∞(1/2)^n. :: Sum is 1/(1−1/2)=2.", "Parametric tangent :: x=t²,y=t³ at t=2. :: dy/dx=(3t²)/(2t)=3.", "Polar circle :: r=2cosθ. :: x²+y²=2x, a circle centered (1,0) with radius 1."),
    "multivariable-vector": topic("A multivariable function changes along many directions. Partial derivatives hold other variables fixed; the gradient points toward steepest local increase.", "Compute each partial, assemble ∇f, and use directional derivative ∇f·u for a unit direction u.", "The gradient is a vector of rates; a directional derivative requires a unit direction to represent rate per unit distance.", "Hill :: f(x,y)=x²+y². :: At (1,2), ∇f=(2,4), pointing outward.", "Temperature :: T=20+3x−2y. :: Moving one unit east changes T by +3; north by -2.", "Directional rate :: ∇f=(2,4), u=(3/5,4/5). :: D_u f=6/5+16/5=22/5."),
    jacobians: topic("The Jacobian matrix contains all first partial derivatives of a coordinate map. Its determinant gives local signed area or volume scaling, so change of variables uses its absolute value.", "Write the transformation and domain, calculate the Jacobian determinant, transform boundaries, and integrate with |J|.", "For polar coordinates the area element is r dr dθ, not simply dr dθ.", "Polar :: x=r cosθ,y=r sinθ. :: |J|=r, so a radius-R disk area is ∫₀²π∫₀ᴿr dr dθ=πR².", "Scaling :: x=2u,y=3v. :: |J|=6; a unit uv-square maps to area 6.", "Shear :: x=u+v,y=v. :: |J|=1, so area is preserved."),
    "beta-gamma": topic("Gamma extends factorial: Γ(n+1)=n! for nonnegative integers. Beta integrates powers on [0,1] and satisfies B(p,q)=Γ(p)Γ(q)/Γ(p+q).", "Check parameter positivity, use recurrence or substitution to simplify, and relate special values to known integrals.", "Γ(0) is undefined; factorial extension does not remove poles at nonpositive integers.", "Factorial :: Γ(5). :: Γ(5)=4!=24.", "Half value :: Γ(1/2). :: It equals √π through the Gaussian integral.", "Beta :: B(2,3)=∫₀¹t(1−t)²dt. :: Γ(2)Γ(3)/Γ(5)=1/12."),
    "series-tests": topic("A series Σa_n converges when its partial sums approach a finite limit. Comparison, ratio, root, alternating, and integral tests apply under different hypotheses.", "Check whether a_n→0 first, identify sign and growth type, then select a test and state what it proves.", "a_n→0 is necessary but not sufficient: the harmonic series diverges.", "Geometric :: Σ_(n=0)^∞(1/3)^n. :: Converges to 3/2 because |r|<1.", "Harmonic :: Σ1/n. :: Diverges even though 1/n→0.", "Alternating :: Σ(-1)^(n+1)/n. :: Converges by alternating test but not absolutely."),
    "curve-tracing": topic("Curve tracing combines domain, intercepts, symmetry, first derivative, second derivative, and asymptotes into a coherent graph.", "Find undefined points and limits, solve f′=0 for turning points, use f″ for concavity, then compare with sampled values.", "A vertical asymptote is a limit statement; a small denominator alone does not prove one if the numerator also vanishes.", "Cubic :: f=x³−3x. :: f′=3x²−3 gives extrema at x=±1.", "Rational :: f=1/(x−2). :: Domain excludes 2 and x=2 is a vertical asymptote.", "Inflection :: f=x³. :: f″=6x changes sign at 0, so the origin is an inflection point."),
    "taylor-two-variables": topic("A two-variable Taylor approximation uses value, gradient, and Hessian near a base point. The quadratic term captures local curvature and mixed interaction.", "At (a,b), compute f, ∇f, and Hessian; then evaluate f(a,b)+∇f·h+(1/2)hᵀHh for a small displacement h.", "Local approximations can become inaccurate far from the expansion point.", "Surface :: f=x²+y² near (1,1). :: For h=(0.1,0.2), exact second-order Taylor gives 2+0.6+0.05=2.65.", "Mixed term :: f=xy near (1,2). :: Expansion 2+2h_x+h_y+h_xh_y is exact.", "Plane :: f=sin x+y near (0,0). :: First-order approximation is x+y."),
    "lagrange-multipliers": topic("At a smooth constrained extremum of f subject to g=c, the objective gradient is parallel to the constraint gradient: ∇f=λ∇g.", "Solve the multiplier equations together with the constraint, then compare all candidates and boundary cases.", "The multiplier condition finds candidates, not automatically maxima; singular constraints need separate inspection.", "Fence :: Maximize xy with x+y=10. :: x=y=5 gives maximum area 25.", "Nearest point :: Minimize x²+y² subject to x+y=2. :: Point (1,1) has minimum squared distance 2.", "Sphere :: Maximize z subject to x²+y²+z²=9. :: Top point (0,0,3) is the maximum."),
    "change-order": topic("A double integral over a region can be computed in either order when the integrand is integrable. Changing order means describing the same region with new inner and outer bounds.", "Sketch the region from the original bounds, project it on the new outer axis, and solve boundary curves for the new inner variable.", "Swapping integral symbols without changing limits usually changes the region.", "Triangle :: 0≤x≤1, 0≤y≤x. :: Reversed order is 0≤y≤1, y≤x≤1.", "Area :: ∫₀¹∫₀ˣ1 dy dx. :: Value is 1/2 in either order.", "Curved region :: 0≤x≤1, x²≤y≤1. :: Reversed: 0≤y≤1, 0≤x≤√y."),
    centroid: topic("The centroid is the mass-weighted average position. For uniform planar density, x̄=(1/A)∫∫_R x dA and ȳ=(1/A)∫∫_R y dA.", "Determine area or mass first, then compute first moments and divide by total. Use symmetry to avoid unnecessary integration.", "A centroid can lie outside a concave region; it is not always a point inside the material.", "Rectangle :: Uniform 6×4 plate. :: Centroid is (3,2) from one corner.", "Triangle :: Vertices (0,0),(6,0),(0,3). :: Centroid is average of vertices, (2,1).", "Two masses :: 2 kg at x=0 and 1 kg at x=6. :: Center of mass x̄=(2·0+1·6)/3=2."),
    "moments-of-inertia": topic("Moment of inertia measures mass distribution about an axis: I=∫r²dm. Material farther from the axis contributes quadratically more.", "Choose the axis, express perpendicular distance r, specify density, and integrate over the object; use the parallel-axis theorem when shifting axes.", "Area moment of inertia in structural engineering and mass moment of inertia have different units and interpretations.", "Point masses :: 1 kg at radius 2 m and 2 kg at radius 1 m. :: I=1·4+2·1=6 kg·m².", "Thin rod :: Uniform mass M, length L about center. :: I=ML²/12.", "Parallel axis :: Disk has I_center=MR²/2. :: About tangent axis, I=MR²/2+MR²=3MR²/2."),
    "integral-engineering": topic("Multiple integrals accumulate density over regions or volumes. They compute mass, average fields, probability, and engineering properties when a single-variable slice is insufficient.", "Describe the domain, choose Cartesian/polar/cylindrical coordinates, include the Jacobian, and integrate density or the required moment.", "A coordinate change without its Jacobian gives the wrong physical units and total.", "Plate mass :: Uniform density 2 kg/m² over a 3×4 m plate. :: Mass ∫∫2 dA=24 kg.", "Disk area :: Radius 2 disk in polar coordinates. :: ∫₀²π∫₀²r dr dθ=4π.", "Mean temperature :: T=x+y on unit square. :: Average ∫₀¹∫₀¹(x+y)dxdy=1."),
    advanced: topic("Advanced calculus combines convergence, multivariable derivatives, optimization, and coordinate changes. Each method is valid only under its continuity, differentiability, or domain assumptions.", "Translate a problem into geometry and notation, choose a theorem with matching hypotheses, compute, then inspect limiting or boundary cases.", "A symbolic result can be wrong at singular points or omitted boundaries even when algebra elsewhere is correct.", "Critical point :: f=x²+y² under x+y=2. :: Constrained minimum at (1,1), value 2.", "Jacobian :: x=2u,y=3v. :: Unit square area scales by 6.", "Series :: Σ_(n=1)^∞1/n². :: It converges by p-series test with p=2."),
  },
};

studioTheoryContent["advanced-concepts"] = {
  "continued-fractions": topic("A continued fraction writes a real number as a₀+1/(a₁+1/(a₂+⋯)). Truncating it gives convergents pₙ/qₙ, often exceptionally accurate for their denominator.", "Take the integer part, invert the fractional remainder, and repeat. Build convergents with pₙ=aₙpₙ₋₁+pₙ₋₂ and the same recurrence for q.", "A decimal rounded before expansion can change later partial quotients dramatically.", "Rational sensor ratio :: Apply Euclid to 13/8: 13=1·8+5, 8=1·5+3, 5=1·3+2, 3=1·2+1. :: 13/8=[1;1,1,1,2], and the final convergent is exact.", "Square-root estimate :: √2=[1;2,2,2,…]. :: Convergents 1, 3/2, 7/5, 17/12 progressively approach 1.4142.", "Gear ratio :: Approximate π by a small-denominator fraction. :: The convergent 22/7≈3.14286 errs by about 0.00126."),
  "famous-problems": topic("A famous problem may be a proved theorem, an open conjecture, or a paradox resolved by changing axioms. Examples connect elementary statements to deep proof methods.", "State the claim with its quantifiers, test small cases to build intuition, then separate numerical evidence from a proof covering every case.", "A billion successful trials do not prove a universal claim over infinitely many integers.", "Collatz orbit :: Start at 6 and apply n/2 for even n or 3n+1 for odd n. :: 6→3→10→5→16→8→4→2→1, one observed orbit but no general proof.", "Four colors :: A planar map has adjacent regions sharing an edge. :: The four-color theorem guarantees a coloring with at most four colors, regardless of map size.", "Fermat equation :: Test n=3 and x=3,y=4. :: 3³+4³=91, not a cube; Fermat's theorem rules out every positive integer triple for all n>2."),
  "stats-inference": topic("Inference uses a sample statistic to estimate an unknown population quantity. A confidence interval adds uncertainty from repeated sampling; a hypothesis test measures conflict with a specified null.", "Check how the data were sampled, compute the estimate and standard error, select a justified critical value, and interpret the interval in population terms.", "A 95% confidence interval does not assign 95% probability to a fixed parameter after the data are observed.", "Election share :: 600 of 1000 sampled voters support a proposal. :: p̂=0.6; approximate 95% margin 1.96√(0.6·0.4/1000)≈0.0304.", "Conversion test :: 55 conversions in 100 visits, test p₀=0.5. :: z=(0.55−0.5)/√(0.25/100)=1; this is weak two-sided evidence.", "Sample planning :: Want margin 0.05 for a proportion near 0.5 at 95%. :: n≈1.96²·0.25/0.05²≈385 independent responses."),
  "differential-equations": topic("A first-order initial value model y′=f(t,y), y(t₀)=y₀ predicts how a state changes from its current value. Exact solutions serve as a check for numerical stepping.", "Identify units and an equilibrium, solve analytically when separable or linear, then compare Euler's yₙ₊₁=yₙ+hf(tₙ,yₙ) with the exact curve.", "Euler's error grows when the step is large relative to the model's time scale.", "Cooling :: T′=−0.2(T−20), T(0)=80. :: T(5)=20+60e⁻¹≈42.1 °C.", "Growth :: P′=0.3P, P(0)=100. :: P(2)=100e⁰·⁶≈182.2.", "Euler check :: y′=y, y(0)=1, h=0.1. :: One Euler step is 1.1; exact y(0.1)=e⁰·¹≈1.1052."),
  "special-functions": topic("Special functions extend elementary operations: Gamma generalizes factorial, Beta normalizes power-law densities, erf integrates the Gaussian kernel, and zeta sums reciprocal powers.", "Check each function's domain, use identities and recurrence relations, and compare numeric values against a known special case.", "A named function can have poles or branch restrictions; evaluating outside the defining integral may require analytic continuation.", "Factorial extension :: Γ(5)=∫₀∞t⁴e⁻ᵗdt. :: Γ(5)=4!=24.", "Beta probability :: B(2,3)=∫₀¹t(1−t)²dt. :: B(2,3)=1/12, so density 12t(1−t)² integrates to 1.", "Basel sum :: ζ(2)=Σₙ₌₁∞1/n². :: ζ(2)=π²/6≈1.645."),
};

studioTheoryContent["statistics-extended"] = {
  "survey-sampling": topic("Stratified sampling estimates a population mean as ΣWₕȳₕ. Independent samples within strata contribute variance ΣWₕ²Sₕ²/nₕ; a finite population correction matters for large sampling fractions.", "Choose strata before sampling, allocate observations using size and within-stratum variation, then weight each stratum estimate by its population share.", "Equal sample sizes across unequal strata generally require weights; an unweighted overall average can be biased.", "District poll :: Urban share 0.6 has 55% support and rural share 0.4 has 45%. :: Weighted support is 0.6·0.55+0.4·0.45=0.51.", "Finite census :: Sample 200 without replacement from N=1000. :: Standard error multiplier is √((1000−200)/(1000−1))≈0.895.", "Neyman allocation :: Two equally sized strata have SDs 10 and 20; total n=90. :: Allocate 30 and 60 observations in proportion to NₕSₕ."),
  "design-of-experiments": topic("An experiment estimates treatment effects by random assignment. Blocking removes known nuisance variation; replication estimates residual noise; factorial designs expose interactions.", "Specify response and factors, randomize within blocks, compute treatment and error sums of squares, then compare mean squares with an F ratio.", "A significant main effect may hide opposing effects across levels of a second factor; inspect interaction first.", "Fertilizer blocks :: Three fields each receive A and B; paired yield differences are 2,3,1. :: Mean treatment gain is 2 units after field blocking.", "Website factorial :: A button adds 2% conversion on desktop but −1% on mobile. :: Device modifies the button effect, so report an interaction.", "ANOVA :: Treatment MS=18, error MS=3. :: F=18/3=6; compare with an F reference distribution for the design's degrees of freedom."),
  "quality-control": topic("A control chart tests whether process variation is stable over time. Capability compares stable process spread with customer specification limits; control and specification limits answer different questions.", "Estimate the process center and σ from stable data, plot time-ordered observations against control limits, then compute Cp and Cpk against specifications.", "A process can be stable yet produce many defects if it is centered poorly or too variable.", "Fill volume :: Target 500 mL, σ=2, specs 494–506. :: Cp=(506−494)/(6·2)=1; the spread exactly fills the tolerance.", "Off-center process :: Mean 503 mL with same specs and σ=2. :: Cpk=min(506−503,503−494)/(3·2)=0.5.", "p chart :: Defect fraction p̄=0.02 in samples of 100. :: Approximate 3σ upper limit is 0.02+3√(0.02·0.98/100)≈0.062."),
  "time-series": topic("A time series combines level, trend, seasonal repetition, and irregular error. Forecasts must respect temporal order; smoothing trades noise reduction for lag.", "Plot by time, choose a seasonal period, fit level or trend, inspect residual autocorrelation, and score forecasts on future observations.", "Random train/test shuffling leaks future information into a forecast evaluation.", "Store sales :: Months show 100,110,120 units. :: Three-month moving average after month 3 is 110 units.", "Exponential smoothing :: Prior forecast 100, observed 120, α=0.25. :: Updated forecast is 0.25·120+0.75·100=105.", "Forecast error :: Actuals 10,12 and forecasts 9,15. :: MAE=(1+3)/2=2 units."),
  nonparametric: topic("Rank and sign tests compare samples with fewer distributional assumptions than parametric mean tests. The test statistic depends on pairing and number of groups.", "For paired measurements use signs or signed ranks; for independent groups rank all observations together and compute Mann–Whitney U or Kruskal–Wallis.", "Mann–Whitney U is not automatically a test of medians when group shapes differ.", "Pain before/after :: Five patients all improve. :: Two-sided sign-test probability is 2/2⁵=0.0625 under equal improvement/worsening chance.", "Two groups :: Scores A={1,2}, B={3,4}. :: A has rank sum 3 and U_A=3−2·3/2=0, complete separation.", "Runs :: Binary outcomes H,H,H,T,T,T form two runs. :: Few runs may suggest clustering versus random order."),
  "multivariate-analysis": topic("Multivariate analysis handles correlated outcomes jointly. PCA diagonalizes covariance; Hotelling's T² generalizes a mean-distance test; MANOVA compares vector means.", "Standardize when units differ, estimate covariance, inspect eigenvalues and eigenvectors, and check whether a joint test adds information beyond separate tests.", "A principal component explains variance, not necessarily a causal mechanism or a meaningful label.", "Correlated sensors :: Covariance [[2,1],[1,2]]. :: Eigenvalues 3 and 1; direction (1,1) captures 75% of total variance.", "Portfolio :: Two assets each have variance 4 and covariance 2. :: Equal-weight portfolio variance is 0.25(4+4+2·2)=3.", "Joint biomarkers :: Treatment shifts two correlated measures by (1,1). :: Mahalanobis distance uses Σ⁻¹ so shared variation is not counted twice."),
  "advanced-inference": topic("Advanced inference compares estimator bias, variance, coverage, and decision error. Likelihood combines evidence from observations; Bayesian updating combines it with a prior.", "Write the sampling model and likelihood, identify the estimand, derive or simulate an interval, and check coverage under repeated synthetic samples.", "A narrow interval can still be unreliable if model assumptions or selection mechanisms are wrong.", "Binomial estimate :: 8 successes in 10 trials. :: Maximum-likelihood p̂=0.8.", "Beta update :: Prior Beta(2,2), then 8 successes and 2 failures. :: Posterior is Beta(10,4), mean 10/14≈0.714.", "Normal mean :: σ=4 known, n=64, sample mean 20. :: Standard error is 0.5; approximate 95% interval is 20±0.98."),
  "official-statistics": topic("Official statistics turn survey and administrative records into comparable population indicators. Definitions, reference periods, weights, and revisions determine what an index means.", "Read the metadata, identify numerator and denominator, apply weights or base-year scaling, and state the population and time period.", "A change in a published rate may reflect a changed definition or sampling frame rather than only real-world change.", "Price index :: Basket costs ₹120 now versus ₹100 in base year. :: Index is 120, implying 20% cumulative basket inflation.", "Birth rate :: 1200 births among 100,000 residents in one year. :: Crude birth rate is 12 per 1000 residents.", "District average :: 60% of people live in A with rate 10%, 40% in B with rate 20%. :: Population-weighted rate is 14%, not 15%."),
  "survival-analysis": topic("Survival analysis models time until an event while retaining right-censored observations. Kaplan–Meier multiplies conditional survival proportions at event times; hazards describe instantaneous event rates.", "Order event times, count subjects at risk just before each event, multiply (1−dᵢ/nᵢ), and mark censoring without treating it as a failure.", "Dropping censored subjects entirely biases estimates when they carried valid follow-up information.", "Machine lifetime :: At day 5, 2 of 10 machines fail. :: Kaplan–Meier survival drops to 8/10=0.8.", "Later event :: One unit is censored after day 5; at day 8, 1 of 7 at risk fails. :: Survival becomes 0.8·6/7≈0.686.", "Constant hazard :: λ=0.1 per year. :: Exponential survival at 5 years is e⁻⁰·⁵≈0.607."),
  "actuarial-reliability": topic("Actuarial models price uncertain future claims and failures using event probabilities, severities, and timing. Expected loss is frequency times average severity before loading and expenses.", "Estimate exposure, claim frequency, claim amount, and uncertainty; discount future payments and test sensitivity to rate changes.", "Expected value alone misses tail risk and does not include administration, capital, or profit loading.", "Warranty reserve :: 1000 devices each have 2% failure probability and ₹500 repair cost. :: Expected repair reserve is 1000·0.02·500=₹10,000.", "Premium :: Expected claims ₹800, expenses ₹100, loading ₹100. :: Indicated premium is ₹1000 per policy.", "Reliability :: Constant failure hazard 0.02 per month. :: Probability of surviving 12 months is e⁻⁰·²⁴≈0.787."),
  "statistical-computing": topic("Statistical computing approximates uncertainty when algebra is difficult. Bootstrap resamples observed units with replacement; permutation tests reshuffle labels under a null of exchangeability.", "Choose the statistic and resampling unit, repeat many simulated samples, inspect the empirical distribution, and report Monte Carlo uncertainty.", "Resampling individual rows is invalid when observations are clustered or serially dependent; resample at the independent unit.", "Bootstrap mean :: Data {2,4,6}; one resample {2,2,6}. :: Resample mean is 10/3 versus observed mean 4.", "Permutation :: Group A={1,2}, B={3,4}; observed mean difference is −2. :: Relabel all 6 possible 2-versus-2 assignments to form an exact null distribution.", "Monte Carlo π :: Uniform points in unit square; 7854 of 10,000 lie inside quarter circle. :: π≈4·0.7854=3.1416."),
  "applied-modelling": topic("Applied models link predictors to outcomes while quantifying error. Linear regression predicts continuous values, logistic regression predicts event probability, and Poisson regression predicts counts.", "Define target and predictors, split data by the intended deployment setting, fit the appropriate link function, then check calibration and residual patterns.", "A strong fitted association does not establish causality, and accuracy on training data can conceal overfitting.", "Hospital odds :: Logistic intercept 0 gives baseline p=0.5; coefficient ln2 for risk factor. :: With factor present, odds double from 1 to 2, so p=2/3.", "Calls :: Poisson model predicts λ=3 arrivals/hour. :: Probability of zero calls is e⁻³≈0.0498.", "Linear demand :: Model sales=20+3·advertising (₹1000 units). :: At advertising=4, prediction is 32 sales units."),
  "school-statistics": topic("School statistics introduces data displays, center, spread, and chance through concrete counts. The right summary depends on data type and skew.", "Organize observations into a frequency table, calculate median or mean as appropriate, visualize honestly, and distinguish replacement from no replacement in probability.", "An average can hide an outlier; always inspect the original distribution or a plot.", "Class marks :: Sorted marks 4,5,7,8,10. :: Median is 7 and mean is 34/5=6.8.", "Library pictograph :: One icon represents 5 books; a row has 6 icons. :: The row represents 30 books.", "Bag draw :: 3 red and 2 blue balls; draw two without replacement. :: P(both red)=(3/5)(2/4)=3/10."),
};

studioTheoryContent["statistics-phase"] = {
  module: topic("A probability model specifies possible outcomes and their chances; statistical inference works in reverse from observed data to unknown model parameters. Discrete mass sums to one, while continuous density integrates to one.", "Start with the outcome type and support, choose a distribution whose assumptions fit, estimate parameters, then compare predictions with observed frequencies.", "Matching a histogram visually is insufficient when observations are dependent or the model's support excludes possible outcomes.", "Quality test :: Each item is defective with probability 0.02 independently. :: Defect count among 100 items is binomial with mean 2.", "Waiting time :: Arrivals occur at rate 3/hour. :: Exponential mean waiting time is 1/3 hour, or 20 minutes.", "Survey :: 240 of 400 respondents agree. :: Sample proportion is 0.6; approximate SE is √(0.6·0.4/400)≈0.0245."),
  distributions: topic("A distribution maps outcomes to probability. Discrete models assign mass to individual values; continuous models assign density whose area over an interval is probability.", "Choose support first, then identify mechanism such as fixed trials, waiting time, sampling without replacement, or symmetric measurement noise. Compare mean, variance, and tail behavior.", "For a continuous variable P(X=a)=0 even if its density at a is positive.", "Dice :: A fair die has six equally likely outcomes. :: P(X≥5)=2/6=1/3.", "Poisson calls :: Average 2 calls per hour. :: P(X=0)=e⁻²≈0.135.", "Normal measurement :: X~N(100,10²). :: P(90<X<110)≈0.6827, the central one-SD area."),
  sampling: topic("A sampling distribution describes how a statistic varies across repeated samples. For independent observations, the mean's standard error is σ/√n; the Central Limit Theorem often makes its standardized shape nearly normal.", "Choose a population model, repeatedly sample the same size, calculate a statistic per sample, and compare the empirical spread with its standard-error formula.", "The CLT concerns the distribution of sample means, not a claim that the original population is normal.", "Factory output :: Individual measurements have σ=12 and n=36. :: Sample-mean standard error is 12/√36=2.", "Sample planning :: Want SE at most 1 with σ=10. :: Need n≥(10/1)²=100 independent measurements.", "Polling :: p=0.4 and n=400. :: Proportion standard error is √(0.4·0.6/400)≈0.0245."),
  inference: topic("A hypothesis test compares observed data with a specified null model; its p-value is a tail probability assuming that null. Confidence intervals report a range of estimates compatible with the data and procedure.", "Write null and alternative first, choose an appropriate standard error and test statistic, calculate a p-value, then report effect size and uncertainty.", "The p-value is not the probability that the null hypothesis is true.", "Coin test :: 60 heads in 100 tosses, H₀:p=0.5. :: z=(0.6−0.5)/√(0.25/100)=2; two-sided p≈0.0455.", "Mean interval :: Sample mean 50, known σ=10, n=100. :: 95% interval is 50±1.96·1=48.04 to 51.96.", "Power :: True proportion 0.6 versus null 0.5. :: Increasing n shrinks SE, making that 0.1 difference easier to detect."),
  regression: topic("Regression predicts an outcome from predictors; residuals are observed minus predicted values. A good fit needs both an appropriate trend and residual behavior consistent with model assumptions.", "Fit coefficients, plot residuals against predictions and time, compute SSE and R², then validate on new data.", "A high R² can coexist with curved residuals or influential points and does not show causation.", "Sales line :: ŷ=5+2x and x=3. :: Predicted sales are 11; if observed y=13, residual is +2.", "Fit quality :: SST=100 and SSE=20. :: R²=1−20/100=0.8, so the fit accounts for 80% of sample variation.", "Outlier :: Four points lie near y=x; add (100,0). :: The far point can pull a least-squares line strongly, so inspect leverage."),
  bayesian: topic("Bayesian inference updates prior probability with likelihood: posterior odds equal prior odds times the likelihood ratio. In low-base-rate settings, false positives can dominate positive results.", "Construct a contingency table or Bayes numerator and denominator, calculate posterior probability, then test sensitivity to prior and test accuracy.", "Sensitivity is P(positive|condition), while positive predictive value is P(condition|positive); they are not interchangeable.", "Screening :: Prevalence 1%, sensitivity 90%, false-positive rate 10%. :: P(condition|positive)=0.009/(0.009+0.099)=1/12≈8.3%.", "Spam filter :: Prior spam 20%, P(flag|spam)=0.8, P(flag|legitimate)=0.05. :: P(spam|flag)=0.16/(0.16+0.04)=0.8.", "Beta coin :: Prior Beta(2,2), observe 3 heads and 1 tail. :: Posterior Beta(5,3) has mean 5/8."),
  stochastic: topic("A stochastic process tracks a state that evolves randomly. Markov chains use transition probabilities; Poisson processes model independent arrivals; queue utilization compares arrival and service rates.", "Identify states and time steps, build a transition matrix or rate model, iterate it, and inspect long-run behavior and parameter sensitivity.", "A stationary distribution depends on the transition model and may not exist uniquely for a reducible chain.", "Weather chain :: Sunny→sunny 0.8, rainy→sunny 0.4. :: If today is sunny, tomorrow's sun probability is 0.8.", "Call arrivals :: Poisson rate 2/hour. :: P(no calls in 1 hour)=e⁻²≈0.135.", "Queue :: Arrival rate 8/hour, service rate 10/hour. :: Utilization ρ=8/10=0.8; a single-server queue is stable only when ρ<1."),
  "advanced-models": topic("Advanced statistical models handle correlated measurements, multimodal data, and information loss. A covariance matrix shapes multivariate-normal ellipses; mixtures combine component densities; KL divergence compares distributions asymmetrically.", "Inspect covariance eigenvectors, compare candidate component counts on held-out data, and quantify uncertainty or divergence with clearly stated reference distribution.", "Adding mixture components can always improve training likelihood yet worsen prediction; validate complexity.", "Covariance ellipse :: Σ=diag(4,1). :: One-standard-deviation contours are twice as wide in x as y.", "Mixture :: 30% of observations come from mean 0 and 70% from mean 10. :: Overall mean is 0.3·0+0.7·10=7.", "Entropy :: Fair binary event has p=0.5. :: H=−2(0.5 log₂0.5)=1 bit."),
};

